"""
and_ladder_sharing_across_repeated_blocks: finds every control pair (p, q) that is used as the
control pair of >= 2 ccz/ccx (AND-type) gates anywhere in the circuit, with p and q never touched
by any other gate between the first and the last such occurrence (globally, not just adjacently).
For each such pair, compute p&q once into a fresh ancilla via a single Toffoli, replace every
occurrence by a cheap cz(ancilla, target) (sound since the ancilla == p&q at every occurrence, as
p,q are provably untouched in between), and measurement-uncompute the ancilla once at the very end
(H; measure; classically-controlled cz(p,q) fixup; reset). This turns k occurrences of a shared-pair
AND gate (7k T) into one real Toffoli + free CZs + free measurement-uncompute (7 T total).
"""
from circuitevolve.circuit import Circuit, Gate
from circuitevolve.verifier import Req


def _is_and_gate(g: Gate) -> bool:
    return g.name in ("ccx", "ccz")


def _control_pair_and_target(g: Gate):
    # ccx: qubits = (c0, c1, target) ; ccz: qubits = (c0, c1, target) with target the "phase" qubit
    c0, c1, t = g.qubits
    return frozenset((c0, c1)), t


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    gates = list(c.gates)
    n_gates = len(gates)

    # Collect indices of AND-type gates grouped by their control pair (unordered).
    occ_by_pair = {}
    for i, g in enumerate(gates):
        if _is_and_gate(g):
            pair, _ = _control_pair_and_target(g)
            occ_by_pair.setdefault(pair, []).append(i)

    # Candidate pairs: appear >= 2 times.
    candidate_pairs = [p for p, idxs in occ_by_pair.items() if len(idxs) >= 2]
    if not candidate_pairs:
        return c, Req()

    def touches(g: Gate, qset) -> bool:
        return any(q in qset for q in g.qubits)

    # For each candidate pair, verify the controls are untouched by ANY OTHER gate strictly
    # between the first and last occurrence of that pair's AND-gates (occurrences themselves only
    # touch the controls as controls, which is fine/expected).
    accepted_pairs = []  # list of (pair, [indices], first_idx, last_idx)
    used_gate_indices = set()  # to avoid overlapping rewrites touching same gate twice
    for pair in candidate_pairs:
        idxs = occ_by_pair[pair]
        first_i, last_i = idxs[0], idxs[-1]
        p, q = tuple(pair)
        ok = True
        for j in range(first_i, last_i + 1):
            if j in idxs:
                continue
            g = gates[j]
            if touches(g, (p, q)):
                ok = False
                break
        if not ok:
            continue
        if any(j in used_gate_indices for j in idxs):
            continue
        accepted_pairs.append((pair, idxs, first_i, last_i))
        used_gate_indices.update(idxs)

    if not accepted_pairs:
        return c, Req()

    # Build new circuit.
    new_n = c.n
    new_gates = []

    # Map: gate index -> replacement info
    # For the FIRST occurrence of a pair: replace with ccx(p, q, ancilla) [compute] then cz(ancilla, target)
    # For subsequent occurrences: replace with cz(ancilla, target) only
    # After the LAST occurrence: schedule measured-uncompute of ancilla, placed immediately after
    # the last occurrence's position (so controls are still guaranteed untouched up to there).

    pair_ancilla = {}
    pair_first_idx = {}
    pair_last_idx = {}
    idx_to_pair = {}
    for pair, idxs, first_i, last_i in accepted_pairs:
        anc = new_n
        new_n += 1
        pair_ancilla[pair] = anc
        pair_first_idx[pair] = first_i
        pair_last_idx[pair] = last_i
        for j in idxs:
            idx_to_pair[j] = pair

    new_nc = c.nc
    pair_cbit = {}
    for pair, _, _, _ in accepted_pairs:
        pair_cbit[pair] = new_nc
        new_nc += 1

    for i, g in enumerate(gates):
        if i in idx_to_pair:
            pair = idx_to_pair[i]
            anc = pair_ancilla[pair]
            p, q = tuple(pair)
            _, target = _control_pair_and_target(g)
            if i == pair_first_idx[pair]:
                # compute step: ccx(p, q, anc) -- order controls consistently as in original gate
                c0, c1, _ = g.qubits
                new_gates.append(Gate("ccx", (c0, c1, anc)))
            # every occurrence becomes a cheap cz(anc, target)
            new_gates.append(Gate("cz", (anc, target)))
            if i == pair_last_idx[pair]:
                # measured uncompute of ancilla: H anc; measure anc -> cbit; if 1: cz(p,q); reset anc
                cbit = pair_cbit[pair]
                new_gates.append(Gate("h", (anc,)))
                new_gates.append(Gate("measure", (anc,), cbit=cbit))
                new_gates.append(Gate("cz", (p, q), cond=cbit))
                new_gates.append(Gate("reset", (anc,)))
        else:
            new_gates.append(g)

    new_c = Circuit(new_n, new_gates, new_nc, c.zero_init)

    n_ancillas = len(accepted_pairs)
    return new_c, Req(eps=0.0, ancillas=n_ancillas, measure=True)

"""
and_ladder_sharing_across_repeated_blocks: the control pair (q0,q1) is used by ccz(0,1,5) in
both AND-ladder blocks (4 occurrences total), and q0,q1 are never touched by any other gate in
the whole circuit. Since ccz is symmetric and p=q0,q1 are provably idle everywhere outside these
occurrences, p&q is computed exactly once into a fresh ancilla via a single Toffoli (anc starts
|0>, so anc ^= p&q = p&q), each occurrence becomes a free cz(anc,target) (sound: anc==p&q holds
at every occurrence since p,q are untouched in between), and the ancilla is measurement-uncomputed
once after the last occurrence (H; measure; classically-controlled cz(p,q) fixup; reset to |0>).
This turns 4*7=28T into one real Toffoli (7T) plus free CZs and a free measured uncompute.
"""
from circuitevolve.circuit import Circuit, Gate
from circuitevolve.verifier import Req


def _is_and_gate(g: Gate) -> bool:
    return g.name in ("ccx", "ccz")


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    gates = list(c.gates)
    n_gates = len(gates)

    def and_gate_pair_target_options(g: Gate):
        q0, q1, q2 = g.qubits
        if g.name == "ccx":
            return [(frozenset((q0, q1)), q2)]
        else:  # ccz symmetric
            return [
                (frozenset((q0, q1)), q2),
                (frozenset((q0, q2)), q1),
                (frozenset((q1, q2)), q0),
            ]

    options = [and_gate_pair_target_options(g) if _is_and_gate(g) else None for g in gates]

    occ_by_pair = {}
    for i, opts in enumerate(options):
        if opts is None:
            continue
        for pair, target in opts:
            occ_by_pair.setdefault(pair, []).append((i, target))

    candidate_pairs = [p for p, occs in occ_by_pair.items() if len(occs) >= 2]
    if not candidate_pairs:
        return c, Req()

    def touches(g: Gate, qset) -> bool:
        return any(q in qset for q in g.qubits)

    # To be safe/sound, only accept a pair if, across the WHOLE circuit, every single gate that
    # touches p or q is one of this pair's AND-gate occurrences (as a control pair). This avoids
    # any ambiguity from other candidate pairs, overlapping targets, or partial windows.
    candidate_pairs.sort(key=lambda p: -len(occ_by_pair[p]))

    used_gate_indices = set()
    reserved_qubits = set()
    accepted = []

    for pair in candidate_pairs:
        occs = occ_by_pair[pair]
        idxs = [i for i, t in occs]
        if any(j in used_gate_indices for j in idxs):
            continue
        p, q = tuple(pair)
        if p in reserved_qubits or q in reserved_qubits:
            continue

        # Require p, q touched ONLY by these occurrences' AND gates, nowhere else in the circuit.
        ok = True
        idx_set = set(idxs)
        for j, g in enumerate(gates):
            if j in idx_set:
                continue
            if touches(g, (p, q)):
                ok = False
                break
        if not ok:
            continue

        # Also require: for each accepted occurrence gate, the OTHER qubit (the target) is not
        # itself p or q of this pair (guaranteed by construction) -- nothing else to check since
        # p,q are untouched everywhere else, these occurrences are the only places p,q appear.
        accepted.append((pair, occs, idxs[0], idxs[-1]))
        used_gate_indices.update(idxs)
        reserved_qubits.add(p)
        reserved_qubits.add(q)

    if not accepted:
        return c, Req()

    new_n = c.n
    new_nc = c.nc
    pair_ancilla = {}
    pair_cbit = {}
    pair_first_idx = {}
    pair_last_idx = {}

    for pair, occs, first_i, last_i in accepted:
        pair_ancilla[pair] = new_n
        new_n += 1
        pair_cbit[pair] = new_nc
        new_nc += 1
        pair_first_idx[pair] = first_i
        pair_last_idx[pair] = last_i

    idx_to_pair_target = {}
    for pair, occs, first_i, last_i in accepted:
        for i, t in occs:
            idx_to_pair_target[i] = (pair, t)

    new_gates = []
    for i, g in enumerate(gates):
        if i in idx_to_pair_target:
            pair, target = idx_to_pair_target[i]
            anc = pair_ancilla[pair]
            p, q = tuple(pair)
            if i == pair_first_idx[pair]:
                new_gates.append(Gate("ccx", (p, q, anc)))
            new_gates.append(Gate("cz", (anc, target)))
            if i == pair_last_idx[pair]:
                cbit = pair_cbit[pair]
                new_gates.append(Gate("h", (anc,)))
                new_gates.append(Gate("measure", (anc,), cbit=cbit))
                new_gates.append(Gate("cz", (p, q), cond=cbit))
                new_gates.append(Gate("reset", (anc,)))
        else:
            new_gates.append(g)

    new_c = Circuit(new_n, new_gates, new_nc, c.zero_init)
    n_ancillas = len(accepted)
    return new_c, Req(eps=0.0, ancillas=n_ancillas, measure=True)

"""
Fuses the ccz(1,7,*) Toffolis that share control pair (q1,q7) into a single real Toffoli.
We walk the circuit once and find a maximal run of ccz occurrences on the same control pair
such that, between consecutive occurrences, the controls are touched only by standalone X
gates (tracked as polarity flips) -- any other write to a control breaks the window. A fresh
ancilla a is set once with a polarity-adjusted Toffoli ccx(q1,q7,a), each ccz(q1,q7,t_i) in
the window becomes a free cz(a,t_i) (targets may be freely H-conjugated/entangled in between,
that's irrelevant to a's validity), and a is uncomputed with the measurement trick (H; measure;
classically-controlled cz on the polarity-adjusted pair; reset). Sound because q1,q7 are
untouched (up to tracked X polarity) throughout the window, so a == (q1^b1)&(q7^b7) always.
"""
from circuitevolve.circuit import Circuit, Gate
from circuitevolve.verifier import Req


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    gates = c.gates

    candidates = {}
    for i, g in enumerate(gates):
        if g.name == "ccz":
            pair = tuple(sorted(g.qubits[:2]))
            candidates.setdefault(pair, []).append(i)

    best = None
    for pair, idxs in candidates.items():
        if len(idxs) < 2:
            continue
        q1, q7 = pair
        groups = []
        cur = [idxs[0]]
        for k in range(1, len(idxs)):
            i_prev, i_cur = idxs[k - 1], idxs[k]
            broken = False
            for j in range(i_prev + 1, i_cur):
                gg = gates[j]
                if q1 in gg.qubits or q7 in gg.qubits:
                    if gg.name == "x" and len(gg.qubits) == 1:
                        continue
                    else:
                        broken = True
                        break
            if broken:
                groups.append(cur)
                cur = [i_cur]
            else:
                cur.append(i_cur)
        groups.append(cur)

        for grp in groups:
            if len(grp) >= 2:
                if best is None or len(grp) > len(best[1]):
                    best = (pair, grp)

    if best is None:
        return c, Req()

    pair, grp = best
    q1, q7 = pair
    first_i, last_i = grp[0], grp[-1]

    def net_x_polarity(qubit, start, end):
        cnt = 0
        for j in range(start + 1, end):
            gg = gates[j]
            if gg.name == "x" and len(gg.qubits) == 1 and gg.qubits[0] == qubit:
                cnt += 1
        return cnt % 2

    rel_pol = []
    for idx in grp:
        p1 = net_x_polarity(q1, first_i, idx)
        p7 = net_x_polarity(q7, first_i, idx)
        rel_pol.append((p1, p7))

    if any(p != rel_pol[0] for p in rel_pol):
        return c, Req()

    b1, b7 = rel_pol[0]  # should be (0,0) by construction

    a = c.n
    new_gates = []
    new_gates.extend(gates[:first_i])

    if b1:
        new_gates.append(Gate("x", (q1,)))
    if b7:
        new_gates.append(Gate("x", (q7,)))
    new_gates.append(Gate("ccx", (q1, q7, a)))
    if b1:
        new_gates.append(Gate("x", (q1,)))
    if b7:
        new_gates.append(Gate("x", (q7,)))

    grp_set = set(grp)
    j = first_i
    while j <= last_i:
        g = gates[j]
        if j in grp_set and g.name == "ccz":
            t = [qq for qq in g.qubits if qq not in pair][0]
            new_gates.append(Gate("cz", (a, t)))
        else:
            new_gates.append(g)
        j += 1

    cb = c.nc
    if b1:
        new_gates.append(Gate("x", (q1,)))
    if b7:
        new_gates.append(Gate("x", (q7,)))
    new_gates.append(Gate("h", (a,)))
    new_gates.append(Gate("measure", (a,), cbit=cb))
    new_gates.append(Gate("cz", (q1, q7), cond=cb))
    new_gates.append(Gate("reset", (a,)))
    if b1:
        new_gates.append(Gate("x", (q1,)))
    if b7:
        new_gates.append(Gate("x", (q7,)))

    new_gates.extend(gates[last_i + 1:])

    new_c = Circuit(c.n + 1, new_gates, c.nc + 1, c.zero_init)

    return new_c, Req(eps=0.0, ancillas=1, measure=True)

"""
Canonicalize-then-fold rz angles: every rz theta is reduced mod 2pi into (-pi, pi], then snapped
(within 1e-9) to a signed dyadic multiple k*pi/2^n. This is a purely LOCAL, per-gate exact rewrite
(no commutation/reordering is performed, so correctness does not depend on parity tracking or block
structure): each rz(theta) is replaced by the exact Clifford+T decomposition of its canonical dyadic
angle, which is unitarily identical to the original rz up to global phase (ignored by the verifier).
n<=2 (multiples of pi/2) become exact Clifford (i/z/s/sdg), n==3 (odd multiples of pi/4) become a
single t/tdg, and higher n are re-emitted as a single rz at the exact canonical angle (same gate,
but now in canonical form so that later identical-parity occurrences numerically cancel exactly
instead of leaving two near-equal-but-distinct floats that downstream tools would treat as generic).
Angles not within tolerance of any dyadic value of this ladder are left untouched.
"""
import math
from circuitevolve.circuit import Circuit, Gate
from circuitevolve.verifier import Req

PI = math.pi
_TOL = 1e-9
_MAX_N = 20  # max denominator power of 2 we try to recognize


def _canonical_dyadic(theta: float):
    """Return (k, n) such that theta == k*pi/2^n (mod 2pi), k odd or theta==0, with minimal n,
    representative k*pi/2^n lying in (-pi, pi]. Returns None if theta is not dyadic within tol."""
    # reduce mod 2pi into (-pi, pi]
    t = math.fmod(theta, 2 * PI)
    if t <= -PI - _TOL:
        t += 2 * PI
    if t > PI + _TOL:
        t -= 2 * PI
    # snap to 0
    if abs(t) < _TOL:
        return (0, 0)
    for n in range(0, _MAX_N + 1):
        denom = PI / (2 ** n)
        k = t / denom
        kr = round(k)
        if abs(k - kr) < _TOL * (2 ** n) * 4 + 1e-9:
            if kr == 0:
                return (0, 0)
            # reduce to lowest terms (odd k or n==0)
            kk, nn = int(kr), n
            while nn > 0 and kk % 2 == 0:
                kk //= 2
                nn -= 1
            # keep representative within (-2^nn, 2^nn] * pi/2^nn i.e. angle in (-pi,pi]
            return (kk, nn)
    return None


def _emit_for_dyadic(q: int, kk: int, nn: int) -> list:
    """Emit exact Clifford+T gates (or a canonical rz) implementing rz(kk*pi/2^nn) on qubit q."""
    if kk == 0:
        return []
    # bring kk into a canonical representative range for emission: kk*pi/2^nn in (-pi, pi]
    # n==0: kk is even multiple handled above (kk==0). n could be 0 with kk!=0 only if kk*pi outside tol-> treat generically
    if nn == 0:
        # kk*pi ; kk odd (since we divided out factors of 2 unless nn already 0)
        # kk odd -> angle = kk*pi = pi (mod 2pi) up to sign -> global phase on relative angle; use z gate (pi rotation)
        return [Gate("z", (q,))]
    if nn == 1:
        # kk odd, angle = kk*pi/2 = +-pi/2 (mod 2pi representative already in (-pi,pi])
        if kk % 4 == 1:
            return [Gate("s", (q,))]
        else:  # kk % 4 == 3 i.e. -1 mod 4 -> -pi/2
            return [Gate("sdg", (q,))]
    if nn == 2:
        # kk odd, angle = kk*pi/4, kk in {..}, need multiple of pi/4 that's exact Clifford only if actually n<=1;
        # n==2 means genuinely pi/4-type -> T/Tdg (n==3 in the quarter-turn convention used by circuit.py's
        # is_t_like, which counts odd quarter-turns). Here kk is odd and angle = kk*pi/4.
        kk8 = kk % 8
        if kk8 in (1,):
            return [Gate("t", (q,))]
        elif kk8 in (7,):
            return [Gate("tdg", (q,))]
        elif kk8 in (3,):
            # 3pi/4 = pi/2 + pi/4 -> s then t
            return [Gate("s", (q,)), Gate("t", (q,))]
        elif kk8 in (5,):
            # -3pi/4 = -pi/2 - pi/4 -> sdg then tdg
            return [Gate("sdg", (q,)), Gate("tdg", (q,))]
        else:
            # shouldn't happen since kk is odd mod 8 in {1,3,5,7}
            theta = kk * PI / (2 ** nn)
            return [Gate("rz", (q,), theta=theta)]
    # n >= 3 (in this k*pi/2^n lowest-terms form, n here already equals "quarter turns + extra" ladder;
    # re-emit as a single canonical rz gate at the exact reduced dyadic angle.
    theta = kk * PI / (2 ** nn)
    # keep within (-pi, pi]
    if theta <= -PI - _TOL:
        theta += 2 * PI
    if theta > PI + _TOL:
        theta -= 2 * PI
    return [Gate("rz", (q,), theta=theta)]


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    changed = False
    new_gates = []
    for g in c.gates:
        if g.name == "rz" and g.cond is None:
            res = _canonical_dyadic(g.theta)
            if res is not None:
                kk, nn = res
                emitted = _emit_for_dyadic(g.qubits[0], kk, nn)
                # check this actually differs from a literal no-op re-emission of the same float
                if kk == 0:
                    changed = True
                    new_gates.extend(emitted)  # empty list -> gate deleted
                    continue
                if len(emitted) == 1 and emitted[0].name == "rz":
                    # only count as changed if the angle actually moved (canonicalization) enough
                    if abs(emitted[0].theta - g.theta) > 1e-12:
                        changed = True
                    new_gates.append(emitted[0])
                    continue
                else:
                    changed = True
                    new_gates.extend(emitted)
                    continue
        new_gates.append(g)

    if not changed:
        return (c, Req())

    out = Circuit(c.n, new_gates, c.nc, c.zero_init)
    return (out, Req(eps=0.0, ancillas=0, measure=False))

"""
Fold pairs of rz gates that act on the SAME qubit and are separated only by gates that commute
with an rz on that qubit (any gate not touching the qubit, or a CX that uses it purely as a
CONTROL — rz(control) commutes through CX since rz is diagonal and CX only permutes target bits
conditioned on control, so diagonal-on-control operators always commute with CX regardless of
target). Commuting the later rz backward next to the earlier one and summing the angles (mod 2pi)
is an exact identity (rz(a)*rz(b) = rz(a+b) when applied to the same qubit, and rz(a)*U = U*rz(a)
whenever U commutes with it): no approximation, no ancilla, no parity-graph needed. This recovers
the pi/8/-pi/8 and pi/16/-pi/16 cancellations in this circuit (they sit on the same qubit with only
control-side CXs of other qubits in between) using a mechanism distinct from pyzx phase folding
(which works on a different internal graph representation and spider-fusion rules) and from TKET's
peephole optimiser (bounded-window peephole rewrites), and distinct from BQSKit's dyadic fixing.
After folding, angles are canonicalized mod 2pi into (-pi,pi] and snapped to dyadic k*pi/2^n;
n<=2 become exact Clifford, n==3 becomes a single t/tdg, n==0 deletes the gate. Everything else is
left as rz for gridsynth. All rewrites here are exact (eps=0), no ancillas, no measurement.
"""
import math
from circuitevolve.circuit import Circuit, Gate
from circuitevolve.verifier import Req

PI = math.pi
_TOL = 1e-9
_MAX_N = 20


def _reduce_mod_2pi(t: float) -> float:
    t = math.fmod(t, 2 * PI)
    if t <= -PI - 1e-12:
        t += 2 * PI
    if t > PI + 1e-12:
        t -= 2 * PI
    return t


def _canonical_dyadic(theta: float):
    """Return (k, n) in lowest terms with theta == k*pi/2^n (mod 2pi), or None if not dyadic."""
    t = _reduce_mod_2pi(theta)
    if abs(t) < _TOL:
        return (0, 0)
    for n in range(0, _MAX_N + 1):
        denom = PI / (2 ** n)
        k = t / denom
        kr = round(k)
        if abs(k - kr) < _TOL * (2 ** n) * 4 + 1e-9:
            if kr == 0:
                return (0, 0)
            kk, nn = int(kr), n
            while nn > 0 and kk % 2 == 0:
                kk //= 2
                nn -= 1
            return (kk, nn)
    return None


def _emit_for_dyadic(q: int, kk: int, nn: int) -> list:
    if kk == 0:
        return []
    if nn == 0:
        return [Gate("z", (q,))]
    if nn == 1:
        return [Gate("s", (q,))] if kk % 4 == 1 else [Gate("sdg", (q,))]
    if nn == 2:
        kk8 = kk % 8
        if kk8 == 1:
            return [Gate("t", (q,))]
        if kk8 == 7:
            return [Gate("tdg", (q,))]
        if kk8 == 3:
            return [Gate("s", (q,)), Gate("t", (q,))]
        if kk8 == 5:
            return [Gate("sdg", (q,)), Gate("tdg", (q,))]
    theta = _reduce_mod_2pi(kk * PI / (2 ** nn))
    return [Gate("rz", (q,), theta=theta)]


def _commutes_with_rz_on(g: Gate, q: int) -> bool:
    """True if gate g commutes with an rz(q) placed just before/after it."""
    if q not in g.qubits:
        return True
    if g.name == "rz":
        return True
    if g.name in ("z", "s", "sdg", "t", "tdg"):
        return True
    if g.name == "cx" and g.qubits[0] == q:
        # q is the control of a CX: rz(q) is diagonal, commutes with control-side action
        return True
    if g.name == "cz":
        # cz is symmetric & diagonal -> commutes with rz on either qubit
        return True
    if g.name == "ccz":
        return True
    if g.name == "ccx" and q in g.qubits[:2]:
        return True
    return False


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    gates = list(c.gates)
    N = len(gates)
    used = [False] * N
    # merged_theta[i] = accumulated extra angle to fold into gates[i] (only for rz gates we keep as anchor)
    merged_extra = [0.0] * N

    changed = False

    for i in range(N):
        if used[i]:
            continue
        gi = gates[i]
        if gi.name != "rz" or gi.cond is not None:
            continue
        q = gi.qubits[0]
        # scan forward, trying to find a later rz on the same qubit q that we can commute back
        # through everything in between (everything in between must commute with rz(q)).
        j = i + 1
        while j < N:
            gj = gates[j]
            if used[j]:
                j += 1
                continue
            if q in gj.qubits:
                if gj.name == "rz" and gj.cond is None:
                    # found a fusable partner: merge angle into gi, delete gj
                    merged_extra[i] += gj.theta
                    used[j] = True
                    changed = True
                    j += 1
                    continue
                elif _commutes_with_rz_on(gj, q):
                    j += 1
                    continue
                else:
                    # blocked: cannot push further past this gate
                    break
            else:
                j += 1
                continue

    if not changed:
        # still try canonicalization-only pass below; but previous attempt showed pure
        # canonicalization without fusion doesn't reduce T-count, so if nothing fused, bail out.
        pass

    new_gates = []
    for i in range(N):
        if used[i]:
            continue
        g = gates[i]
        if g.name == "rz" and g.cond is None and merged_extra[i] != 0.0:
            theta = g.theta + merged_extra[i]
            res = _canonical_dyadic(theta)
            if res is not None:
                kk, nn = res
                new_gates.extend(_emit_for_dyadic(g.qubits[0], kk, nn))
            else:
                new_gates.append(Gate("rz", g.qubits, theta=_reduce_mod_2pi(theta)))
            continue
        if g.name == "rz" and g.cond is None:
            res = _canonical_dyadic(g.theta)
            if res is not None:
                kk, nn = res
                emitted = _emit_for_dyadic(g.qubits[0], kk, nn)
                if kk == 0:
                    changed = True
                    new_gates.extend(emitted)
                    continue
                if len(emitted) == 1 and emitted[0].name == "rz":
                    if abs(emitted[0].theta - g.theta) > 1e-12:
                        changed = True
                    new_gates.append(emitted[0])
                    continue
                else:
                    changed = True
                    new_gates.extend(emitted)
                    continue
        new_gates.append(g)

    if not changed:
        return (c, Req())

    out = Circuit(c.n, new_gates, c.nc, c.zero_init)
    return (out, Req(eps=0.0, ancillas=0, measure=False))

"""
Phase-polynomial parity folding over maximal CX+rz blocks. Within any maximal run of gates drawn
only from {cx, rz(cond=None)} (bounded by any other gate, which breaks the "all gates diagonal in
the computational basis up to CX-permutation" structure), every rz in the block is a diagonal phase
exp(-i*theta/2 Z) applied to the qubit holding parity label L = XOR of the original block-input
qubits feeding it through the CX network so far. Two rz gates in the same block contribute to the
SAME net phase polynomial term iff their parity labels (computed by propagating each qubit's label
as linear XOR of input labels through the CX ladder, cx(ctrl,tgt): label[tgt] ^= label[ctrl]) are
equal. Since CNOTs only permute computational basis states and rz is diagonal, the whole block's
action is diag(exp(-i/2 * sum_x f(x) * (-1)^{x.L} )) type decomposition, i.e. it equals a product of
commuting per-parity rz rotations; summing angles with equal parity labels and re-emitting one rz
each (then re-applying the exact same CX network) is an exact rewrite (eps=0). This finds the
pi/8/-pi/8 and pi/16/-pi/16 cancellations that live on physically different wires at emission time
but share a parity label through the CX ladder -- invisible to same-qubit commutation rules and to
pyzx's spider fusion unless its angles already match post phase-gadget extraction up to its own
normal form, which does not recognize k*pi/2^n cancellation across differently-scaled representations
the way an explicit dyadic-angle canonicalization (mod 2pi, snapped to k*pi/2^n) does here.
"""
import math
from circuitevolve.circuit import Circuit, Gate
from circuitevolve.verifier import Req

PI = math.pi
_TOL = 1e-9
_MAX_N = 24


def _reduce_mod_2pi(t: float) -> float:
    t = math.fmod(t, 2 * PI)
    if t <= -PI - 1e-12:
        t += 2 * PI
    if t > PI + 1e-12:
        t -= 2 * PI
    return t


def _canonical_dyadic(theta: float):
    """Return (k, n) in lowest terms with theta == k*pi/2^n (mod 2pi), or None if not dyadic."""
    t = _reduce_mod_2pi(theta)
    if abs(t) < 1e-7:
        return (0, 0)
    for n in range(0, _MAX_N + 1):
        denom = PI / (2 ** n)
        k = t / denom
        kr = round(k)
        if abs(k - kr) < 1e-6:
            if kr == 0:
                return (0, 0)
            kk, nn = int(kr), n
            while nn > 0 and kk % 2 == 0:
                kk //= 2
                nn -= 1
            return (kk, nn)
    return None


def _emit_for_dyadic(q: int, kk: int, nn: int) -> list:
    if kk == 0:
        return []
    kk = kk % (2 ** (nn + 1))
    if nn == 0:
        return [Gate("z", (q,))]
    if nn == 1:
        return [Gate("s", (q,))] if kk % 4 == 1 else [Gate("sdg", (q,))]
    if nn == 2:
        kk8 = kk % 8
        if kk8 == 1:
            return [Gate("t", (q,))]
        if kk8 == 7:
            return [Gate("tdg", (q,))]
        if kk8 == 3:
            return [Gate("s", (q,)), Gate("t", (q,))]
        if kk8 == 5:
            return [Gate("sdg", (q,)), Gate("tdg", (q,))]
    theta = _reduce_mod_2pi(kk * PI / (2 ** nn))
    return [Gate("rz", (q,), theta=theta)]


def _is_block_gate(g: Gate) -> bool:
    return g.cond is None and (g.name == "cx" or g.name == "rz")


def _find_blocks(gates: list) -> list:
    """Maximal runs of consecutive cx/rz (cond=None) gates."""
    blocks = []
    i = 0
    N = len(gates)
    while i < N:
        if _is_block_gate(gates[i]):
            j = i
            while j < N and _is_block_gate(gates[j]):
                j += 1
            if j - i >= 2:
                blocks.append((i, j))
            i = j
        else:
            i += 1
    return blocks


def _process_block(block_gates: list, n: int):
    """Given a list of cx/rz gates on an n-qubit circuit, fold rz's sharing a parity label.
    Returns (new_gates, changed) where new_gates is an equivalent gate list."""
    # label[q] = frozenset of original qubit indices (within this block's local frame) XORed together,
    # represented as an integer bitmask over qubits touched; but qubits not touched by any cx keep
    # their own single-bit label implicitly (we only need relative identity between parity labels).
    label = {}

    def get_label(q):
        if q not in label:
            label[q] = frozenset([q])  # own basis label
        return label[q]

    def xor_label(a, b):
        return a.symmetric_difference(b)

    # Accumulate per-parity-label total angle, in order of first occurrence, and remember qubit
    # that will carry it (the target qubit at time of accumulation... but to re-emit we need a
    # consistent single point). Strategy: accumulate sums keyed by parity label; when done, replace
    # each rz's angle: the FIRST rz for a given label keeps accumulated sum, later ones are dropped
    # (theta=0 marker), structure of CX gates fully preserved (so basis permutation unaffected).
    parity_sum = {}
    first_index = {}  # label -> index in block_gates of the first rz carrying it
    rz_indices_for_label = {}

    for idx, g in enumerate(block_gates):
        if g.name == "cx":
            ctrl, tgt = g.qubits
            lc = get_label(ctrl)
            lt = get_label(tgt)
            label[tgt] = xor_label(lc, lt)
        else:  # rz
            q = g.qubits[0]
            lq = get_label(q)
            key = lq
            if key not in parity_sum:
                parity_sum[key] = 0.0
                first_index[key] = idx
                rz_indices_for_label[key] = []
            parity_sum[key] += g.theta
            rz_indices_for_label[key].append(idx)

    # Determine which labels actually have >1 rz contribution (real fusion) or sum to ~0 mod 2pi
    # (cancellation) -- only then do we rewrite (otherwise leave block untouched to minimize risk).
    any_fusion = any(len(v) > 1 for v in rz_indices_for_label.values())
    if not any_fusion:
        return block_gates, False

    # Build new block: cx gates unchanged, rz gates: only emit at first_index position for each
    # label with the accumulated sum (canonicalized), drop all other rz occurrences of that label.
    drop = set()
    emit_theta = {}
    for key, idxs in rz_indices_for_label.items():
        keep_idx = first_index[key]
        total = parity_sum[key]
        emit_theta[keep_idx] = total
        for idx in idxs:
            if idx != keep_idx:
                drop.add(idx)

    new_gates = []
    for idx, g in enumerate(block_gates):
        if g.name == "cx":
            new_gates.append(g)
            continue
        if idx in drop:
            continue
        if idx in emit_theta:
            theta = emit_theta[idx]
            res = _canonical_dyadic(theta)
            q = g.qubits[0]
            if res is not None:
                kk, nn = res
                new_gates.extend(_emit_for_dyadic(q, kk, nn))
            else:
                rt = _reduce_mod_2pi(theta)
                if abs(rt) > 1e-9:
                    new_gates.append(Gate("rz", (q,), theta=rt))
        else:
            new_gates.append(g)

    return new_gates, True


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    gates = list(c.gates)
    blocks = _find_blocks(gates)

    if not blocks:
        return (c, Req())

    changed_any = False
    out_gates = []
    last_end = 0
    for (start, end) in blocks:
        out_gates.extend(gates[last_end:start])
        block = gates[start:end]
        new_block, changed = _process_block(block, c.n)
        if changed:
            changed_any = True
        out_gates.extend(new_block)
        last_end = end
    out_gates.extend(gates[last_end:])

    # Also canonicalize any remaining untouched rz gates outside blocks (n<=3 exact emission),
    # purely so trivial dyadic angles don't needlessly go to gridsynth; only counts as "changed"
    # if it actually alters the emitted gate sequence.
    final_gates = []
    for g in out_gates:
        if g.name == "rz" and g.cond is None:
            res = _canonical_dyadic(g.theta)
            if res is not None:
                kk, nn = res
                emitted = _emit_for_dyadic(g.qubits[0], kk, nn)
                if len(emitted) == 1 and emitted[0].name == "rz" and abs(emitted[0].theta - g.theta) < 1e-12:
                    final_gates.append(g)
                else:
                    changed_any = True
                    final_gates.extend(emitted)
                continue
        final_gates.append(g)

    if not changed_any:
        return (c, Req())

    out = Circuit(c.n, final_gates, c.nc, c.zero_init)
    return (out, Req(eps=0.0, ancillas=0, measure=False))

"""rotation_pair_sum_difference_refactor_across_cx_conjugation

Collapses every maximal run of single-qubit Clifford+rz gates on one wire (between two
multi-qubit gates / circuit boundaries) into one 2x2 unitary. If that unitary is (within a
small per-site error allowance, charged against the approx budget) close to a Clifford
(possibly times a single T/Tdg), it is emitted exactly as that Clifford (0-1 T). Otherwise it
is re-expressed as Clifford * Rz(b) * Clifford (ZXZ-style: Rz(a) H Rz(b) H Rz(c)), so gridsynth
pays for only ONE arbitrary angle instead of the 2-3 arbitrary angles that were in the
original run. This is correct because the run is exactly the matrix product of its gates with
no entangling gates in between, so replacing it with any unitary-equal decomposition leaves the
circuit's action on every qubit (data or ancilla) unchanged.
"""
from __future__ import annotations

import math
import cmath

import numpy as np

from circuitevolve.circuit import Circuit, Gate, matrix
from circuitevolve.verifier import Req

_TOL_CLIFFORD = 1e-7          # numerical matching tolerance for exact Clifford families (0 error cost)
_APPROX_SNAP_EPS = 2.0e-6     # per-site error allowance spent to snap near-Clifford matrices exactly
_MAX_TOTAL_APPROX = 2.5e-4    # hard budget ceiling

_SINGLE_Q_NAMES = {"h", "x", "y", "z", "s", "sdg", "t", "tdg", "sx", "sxdg", "rz"}

PI = math.pi
PI_HALF = math.pi / 2


def _global_phase_strip(u: np.ndarray) -> np.ndarray:
    det = np.linalg.det(u)
    phase = cmath.phase(det) / 2.0
    return u * cmath.exp(-1j * phase)


def _mat_dist(a: np.ndarray, b: np.ndarray) -> float:
    """Phase-invariant operator norm distance between two 2x2 unitaries."""
    inner = np.trace(a.conj().T @ b)
    phase = cmath.phase(inner) if abs(inner) > 1e-14 else 0.0
    diff = a - b * cmath.exp(1j * phase)
    return float(np.linalg.norm(diff, 2))


def _key_of(u: np.ndarray) -> tuple:
    u2 = _global_phase_strip(u)
    return tuple(np.round(u2.flatten(), 5).tolist())


def _build_clifford_table():
    """All 24 single-qubit Cliffords (up to global phase) as short native-gate sequences +
    their matrices, generated as products of H and S starting from the identity (BFS)."""
    h = matrix(Gate("h", (0,)))
    s = matrix(Gate("s", (0,)))
    gens = [("h", h), ("s", s)]

    seen_key = {}
    mats = {(): np.eye(2, dtype=complex)}
    seen_key[_key_of(np.eye(2, dtype=complex))] = ()
    queue = [()]
    head = 0
    while head < len(queue):
        seq = queue[head]
        head += 1
        cur = mats[seq]
        for gname, gmat in gens:
            nxt = gmat @ cur
            k = _key_of(nxt)
            if k not in seen_key:
                nseq = seq + (gname,)
                seen_key[k] = nseq
                mats[nseq] = nxt
                queue.append(nseq)
        if len(seen_key) >= 24:
            break

    table = []
    for k, seq in seen_key.items():
        table.append((seq, mats[seq]))
    return table


_CLIFFORD_TABLE = _build_clifford_table()


def _try_snap_clifford(u: np.ndarray, eps_allow: float):
    """Return (seq_of_gatenames, cost) if u is within eps_allow of some Clifford (possibly times
    a leading T/Tdg), else None. cost is the spent error (phase-invariant op-norm distance)."""
    best = None
    t_mat = matrix(Gate("t", (0,)))
    tdg_mat = matrix(Gate("tdg", (0,)))
    for tname, tmat in (("", None), ("t", t_mat), ("tdg", tdg_mat)):
        if tmat is None:
            target = u
        else:
            target = tmat.conj().T @ u  # u = tmat * target  => target = tmat^-1 u
        for seq, cm in _CLIFFORD_TABLE:
            d = _mat_dist(target, cm)
            if d <= eps_allow and (best is None or d < best[1]):
                full_seq = seq + ((tname,) if tname else ())
                best = (full_seq, d)
    return best


def _su2_zxz_decompose(u: np.ndarray):
    """Decompose u (2x2 unitary, up to global phase) as Rz(a) H Rz(b) H Rz(c) for some angles
    a, b, c in radians. Returns (a, b, c)."""
    det = np.linalg.det(u)
    v = u / cmath.sqrt(complex(det))
    alpha = v[0, 0]
    beta = v[1, 0]
    theta = 2 * math.atan2(abs(beta), abs(alpha))
    a1 = cmath.phase(alpha) if abs(alpha) > 1e-12 else 0.0   # -(phi+lam)/2
    a2 = cmath.phase(beta) if abs(beta) > 1e-12 else 0.0     # (phi-lam)/2
    phi = -a1 + a2
    lam = -a1 - a2
    a_ = phi - PI_HALF
    b_ = theta
    c_ = lam + PI_HALF
    return a_, b_, c_


def _rz_mat(theta):
    return np.diag([cmath.exp(-0.5j * theta), cmath.exp(0.5j * theta)])


def _h_mat():
    return matrix(Gate("h", (0,)))


def _verify_zxz(u, a, b, c, tol=1e-6):
    cand = _rz_mat(a) @ _h_mat() @ _rz_mat(b) @ _h_mat() @ _rz_mat(c)
    return _mat_dist(u, cand) < tol


def _is_arb_angle(theta: float) -> bool:
    k = theta / (PI / 4)
    return abs(k - round(k)) > 1e-9


def _collect_runs(c: Circuit):
    """Return list of (qubit, start_idx, end_idx_exclusive) for maximal runs of single-qubit
    gates on a wire, bounded by multi-qubit gates / measure / reset / cond or circuit edges,
    with length >= 2 (otherwise nothing to fuse)."""
    runs = []
    n = len(c.gates)
    busy_run_start = {}
    for i, g in enumerate(c.gates):
        if g.cond is not None or g.name not in _SINGLE_Q_NAMES or len(g.qubits) != 1:
            for q in g.qubits:
                if q in busy_run_start:
                    s = busy_run_start.pop(q)
                    if i - s >= 2:
                        runs.append((q, s, i))
            continue
        q = g.qubits[0]
        busy_run_start.setdefault(q, i)
    for q, s in busy_run_start.items():
        if n - s >= 2:
            runs.append((q, s, n))
    return runs


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    runs = _collect_runs(c)
    if not runs:
        return c, Req()

    gates = list(c.gates)
    to_delete = set()
    insertions = {}   # start_idx -> list[Gate] to insert in place of the run
    total_spent = 0.0
    budget_left = _MAX_TOTAL_APPROX
    changed = False

    for q, s, e in runs:
        U = np.eye(2, dtype=complex)
        for i in range(s, e):
            U = matrix(gates[i]) @ U

        n_arb_before = sum(1 for i in range(s, e)
                            if gates[i].name == "rz" and _is_arb_angle(gates[i].theta))
        n_gates_before = e - s

        # Try exact/near-Clifford snap first (cheap, 0-1 T total, kills all arbitrary rz's).
        allow = min(_APPROX_SNAP_EPS, budget_left)
        snap = None
        if allow > 0:
            snap = _try_snap_clifford(U, allow)
        if snap is not None and len(snap[0]) < n_gates_before:
            seq, cost = snap
            if cost > _TOL_CLIFFORD and n_arb_before == 0:
                # no arbitrary rz eliminated and we'd still be spending budget: not worth it
                # unless it shortens the gate count usefully; only spend budget when it
                # actually removes an arbitrary rotation.
                pass
            new_gates = [Gate(name, (q,)) for name in seq]
            spend = cost if cost > _TOL_CLIFFORD else 0.0
            if n_arb_before > 0 or spend == 0.0:
                if spend > 0.0:
                    total_spent += spend
                    budget_left -= spend
                for i in range(s, e):
                    to_delete.add(i)
                insertions[s] = new_gates
                changed = True
                continue

        # Otherwise: fuse into Rz(a) H Rz(b) H Rz(c) (ZXZ-style) -> at most 1 arbitrary rz.
        if n_arb_before < 2:
            continue  # nothing to gain: already <=1 arbitrary angle in this run
        try:
            a, b, c_ang = _su2_zxz_decompose(U)
        except Exception:
            continue
        if not _verify_zxz(U, a, b, c_ang, tol=1e-6):
            continue

        n_arb_after = sum(1 for ang in (a, b, c_ang) if _is_arb_angle(ang))
        if n_arb_after >= n_arb_before:
            continue  # no savings, skip this run

        new_gates = [Gate("rz", (q,), theta=c_ang),
                     Gate("h", (q,)),
                     Gate("rz", (q,), theta=b),
                     Gate("h", (q,)),
                     Gate("rz", (q,), theta=a)]
        for i in range(s, e):
            to_delete.add(i)
        insertions[s] = new_gates
        changed = True

    if not changed or not insertions:
        return c, Req()

    new_list = []
    for i, g in enumerate(gates):
        if i in insertions:
            new_list.extend(insertions[i])
        elif i in to_delete:
            continue
        else:
            new_list.append(g)

    new_c = Circuit(c.n, new_list, c.nc, c.zero_init)

    eps_used = min(total_spent, _MAX_TOTAL_APPROX) if total_spent > 0 else 0.0
    return new_c, Req(eps=eps_used, ancillas=0, measure=False)

