        seq = queue[head]
        head += 1
        cur = mats[seq]
        for gname, gmat in gens:
            nxt = gmat @ cur
            k = _key_of(nxt)
            if k not in seen_key:
                nseq = seq + (gname,)
                seen_key[k] = nseq
                mats[nseq] = nxt
                queue.append(nseq)
        if len(seen_key) >= 24:
            break

    table = []
    for k, seq in seen_key.items():
        table.append((seq, mats[seq]))
    return table


_CLIFFORD_TABLE = _build_clifford_table()


def _try_snap_clifford(u: np.ndarray, eps_allow: float):
    """Return (seq_of_gatenames, cost) if u is within eps_allow of some Clifford (possibly times
    a leading T/Tdg), else None. cost is the spent error (phase-invariant op-norm distance)."""
    best = None
    t_mat = matrix(Gate("t", (0,)))
    tdg_mat = matrix(Gate("tdg", (0,)))
    for tname, tmat in (("", None), ("t", t_mat), ("tdg", tdg_mat)):
        if tmat is None:
            target = u
        else:
            target = tmat.conj().T @ u  # u = tmat * target  => target = tmat^-1 u
        for seq, cm in _CLIFFORD_TABLE:
            d = _mat_dist(target, cm)
            if d <= eps_allow and (best is None or d < best[1]):
                full_seq = seq + ((tname,) if tname else ())
                best = (full_seq, d)
    return best


def _su2_zxz_decompose(u: np.ndarray):
    """Decompose u (2x2 unitary, up to global phase) as Rz(a) H Rz(b) H Rz(c) for some angles
    a, b, c in radians. Returns (a, b, c)."""
    det = np.linalg.det(u)
    v = u / cmath.sqrt(complex(det))
    alpha = v[0, 0]
    beta = v[1, 0]
    theta = 2 * math.atan2(abs(beta), abs(alpha))
    a1 = cmath.phase(alpha) if abs(alpha) > 1e-12 else 0.0   # -(phi+lam)/2
    a2 = cmath.phase(beta) if abs(beta) > 1e-12 else 0.0     # (phi-lam)/2
    phi = -a1 + a2
    lam = -a1 - a2
    a_ = phi - PI_HALF
    b_ = theta
    c_ = lam + PI_HALF
    return a_, b_, c_


def _rz_mat(theta):
    return np.diag([cmath.exp(-0.5j * theta), cmath.exp(0.5j * theta)])


def _h_mat():
    return matrix(Gate("h", (0,)))


def _verify_zxz(u, a, b, c, tol=1e-6):
    cand = _rz_mat(a) @ _h_mat() @ _rz_mat(b) @ _h_mat() @ _rz_mat(c)
    return _mat_dist(u, cand) < tol


def _is_arb_angle(theta: float) -> bool:
    k = theta / (PI / 4)
    return abs(k - round(k)) > 1e-9


def _collect_runs(c: Circuit):
    """Return list of (qubit, start_idx, end_idx_exclusive) for maximal runs of single-qubit
    gates on a wire, bounded by multi-qubit gates / measure / reset / cond or circuit edges,
    with length >= 2 (otherwise nothing to fuse)."""
    runs = []
    n = len(c.gates)
    busy_run_start = {}
    for i, g in enumerate(c.gates):
        is_plain_1q = (
            g.cond is None
            and g.name in _SINGLE_Q_NAMES
            and len(g.qubits) == 1
        )
        if not is_plain_1q:
            for q in g.qubits:
                if q in busy_run_start:
                    s = busy_run_start.pop(q)
                    if i - s >= 2:
                        runs.append((q, s, i))
            continue
        q = g.qubits[0]
        busy_run_start.setdefault(q, i)
    for q, s in busy_run_start.items():
        if n - s >= 2:
            runs.append((q, s, n))
    return runs


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    runs = _collect_runs(c)
    if not runs:
        return c, Req()

    gates = list(c.gates)
    to_delete = set()
    insertions = {}   # start_idx -> list[Gate] to insert in place of the run
    total_spent = 0.0
    budget_left = _MAX_TOTAL_APPROX
    changed = False

    for q, s, e in runs:
        # Sanity: every gate in the run must actually be a plain single-qubit gate on q.
        ok = True
        U = np.eye(2, dtype=complex)
        for i in range(s, e):
            g = gates[i]
            if g.cond is not None or g.name not in _SINGLE_Q_NAMES or g.qubits != (q,):
                ok = False
                break
            U = matrix(g) @ U
        if not ok:
            continue

        n_arb_before = sum(1 for i in range(s, e)
                            if gates[i].name == "rz" and _is_arb_angle(gates[i].theta))
        n_gates_before = e - s

        # Try exact/near-Clifford snap first (cheap, 0-1 T total, kills all arbitrary rz's).
        allow = min(_APPROX_SNAP_EPS, budget_left)
        snap = None
        if allow > 0:
            snap = _try_snap_clifford(U, allow)
        handled = False
        if snap is not None and len(snap[0]) < n_gates_before:
            seq, cost = snap
            spend = cost if cost > _TOL_CLIFFORD else 0.0
            if n_arb_before > 0 or spend == 0.0:
                new_gates = [Gate(name, (q,)) for name in seq]
                if spend > 0.0:
                    total_spent += spend
                    budget_left -= spend
                for i in range(s, e):
                    to_delete.add(i)
                insertions[s] = new_gates
                changed = True
                handled = True

        if handled:
            continue

        # Otherwise: fuse into Rz(a) H Rz(b) H Rz(c) (ZXZ-style) -> at most 1 arbitrary rz.
        if n_arb_before < 2:
            continue  # nothing to gain: already <=1 arbitrary angle in this run
        try:
            a, b, c_ang = _su2_zxz_decompose(U)
        except Exception:
            continue
        if not _verify_zxz(U, a, b, c_ang, tol=1e-6):
            continue

        n_arb_after = sum(1 for ang in (a, b, c_ang) if _is_arb_angle(ang))
        if n_arb_after >= n_arb_before:
            continue  # no savings, skip this run

        new_gates = [Gate("rz", (q,), theta=c_ang),
                     Gate("h", (q,)),
                     Gate("rz", (q,), theta=b),
                     Gate("h", (q,)),
                     Gate("rz", (q,), theta=a)]
        for i in range(s, e):
            to_delete.add(i)
        insertions[s] = new_gates
        changed = True

    if not changed or not insertions:
        return c, Req()

    new_list = []
    for i, g in enumerate(gates):
        if i in insertions:
            new_list.extend(insertions[i])
        elif i in to_delete:
            continue
        else:
            new_list.append(g)

    new_c = Circuit(c.n, new_list, c.nc, c.zero_init)

    eps_used = min(total_spent, _MAX_TOTAL_APPROX) if total_spent > 0 else 0.0
    return new_c, Req(eps=eps_used, ancillas=0, measure=False)

"""
ccz_from_t_cx_ladder_then_measured_and_sharing
================================================
Finds the standard 7-T CCZ T-ladder written as the 8-gate sequence
    cx a,t; tdg t; cx b,t; t t; cx a,t; tdg t; cx b,t; t t
(on any target wire t with distinct controls a,b), which is exactly CCZ(a,b,t) up to the
Clifford/phase structure it already encodes -- an exact rewrite, the inverse of the usual
Toffoli -> T-ladder decomposition. Every match is lifted to a single `ccz` gate. We then look
for groups of >=2 lifted ccz's that share the same unordered control pair {p,q} with no
intervening gate touching p or q: such a group is fused by computing p&q once into a fresh
ancilla (Toffoli), replacing every ccz in the group by a free cz(ancilla, other-wire), and
uncomputing the ancilla with the measurement trick (H; measure; classically-controlled cz(p,q)
fixup; reset) -- sound because p,q are untouched throughout so the ancilla equals p&q at every
use, and the measured uncompute exactly inverts the Toffoli compute step. Net: 7*m T -> 7 T per
fused group of size m; unfused lifted ccz's stay as single 7-T Toffolis (no worse than before).
"""
from __future__ import annotations

from circuitevolve.circuit import Circuit, Gate
from circuitevolve.verifier import Req


def _is_t(g, qb):
    return g.name == "t" and g.qubits == (qb,)


def _is_tdg(g, qb):
    return g.name == "tdg" and g.qubits == (qb,)


def _is_cx_to(g, c, t):
    return g.name == "cx" and g.qubits == (c, t)


def _try_match(gates, start):
    """Try to match the 8-gate CCZ T-ladder starting exactly at `start`.
    Pattern: cx a,t; tdg t; cx b,t; t t; cx a,t; tdg t; cx b,t; t t
    Returns (a, b, t) on success else None.
    """
    n = len(gates)
    if start + 8 > n:
        return None
    g0 = gates[start]
    if g0.name != "cx":
        return None
    a, t = g0.qubits
    if not _is_tdg(gates[start + 1], t):
        return None
    g2 = gates[start + 2]
    if g2.name != "cx" or g2.qubits[1] != t:
        return None
    b = g2.qubits[0]
    if a == b:
        return None
    if not _is_t(gates[start + 3], t):
        return None
    if not _is_cx_to(gates[start + 4], a, t):
        return None
    if not _is_tdg(gates[start + 5], t):
        return None
    if not _is_cx_to(gates[start + 6], b, t):
        return None
    if not _is_t(gates[start + 7], t):
        return None
    return a, b, t


def _lift_all(gates):
    """Greedy left-to-right scan, replacing each non-overlapping matched 8-gate ladder
    with a single ccz(a,b,t). Returns (new_gate_list, num_lifted)."""
    out = []
    i = 0
    n = len(gates)
    count = 0
    while i < n:
        res = _try_match(gates, i)
        if res is not None:
            a, b, t = res
            out.append(Gate("ccz", (a, b, t)))
            i += 8
            count += 1
        else:
            out.append(gates[i])
            i += 1
    return out, count


def _group_fusable(gates):
    """Scan the (lifted) gate list and identify maximal runs of ccz gates that share the
    same unordered control pair {p,q}, with no intervening gate (of any kind) touching p or q.
    Returns a list of groups; each group is a dict with 'pair', 'indices' (list of gate index),
    'others' (list of the third wire for each occurrence)."""
    active = {}     # frozenset(pair) -> {'indices':[...], 'others':[...]}
    finished = []

    def close(pair):
        g = active.pop(pair)
        finished.append({"pair": pair, "indices": g["indices"], "others": g["others"]})

    for idx, g in enumerate(gates):
        if g.name == "ccz":
            a, b, t = g.qubits
            pair = frozenset((a, b))
            touched = {a, b, t}
            # close any active group whose pair wires are touched by this gate, except itself
            for p in [p for p in active if p != pair and (touched & p)]:
                close(p)
            if pair not in active:
                active[pair] = {"indices": [], "others": []}
            active[pair]["indices"].append(idx)
            active[pair]["others"].append(t)
        else:
            touched = set(g.qubits)
            for p in [p for p in active if touched & p]:
                close(p)
    for p in list(active.keys()):
        close(p)
    return finished


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    gates = list(c.gates)

    lifted, n_lifted = _lift_all(gates)
    if n_lifted == 0:
        return c, Req()

    groups = _group_fusable(lifted)
    fusable_groups = [g for g in groups if len(g["indices"]) >= 2]
    if not fusable_groups:
        # Lifting alone doesn't change T-count (8 T-like gates -> 1 Toffoli = 7T is the same
        # cost as before under the T-count-after-gridsynth metric only if nothing fuses; the
        # ladder's 4 t/tdg on the shared-target side plus 4 on the other were already costed
        # as explicit T gates equal to a Toffoli's worth, so with no fusion there's no gain).
        return c, Req()

    idx_to_group = {}
    for gi, grp in enumerate(fusable_groups):
        for idx in grp["indices"]:
            idx_to_group[idx] = gi

    n_old = c.n
    n_groups = len(fusable_groups)
    new_n = n_old + n_groups
    ancilla_of_group = {gi: n_old + gi for gi in range(n_groups)}

    nc_old = c.nc
    cbit_of_group = {gi: nc_old + gi for gi in range(n_groups)}
    new_nc = nc_old + n_groups

    first_idx_of_group = {gi: min(grp["indices"]) for gi, grp in enumerate(fusable_groups)}
    last_idx_of_group = {gi: max(grp["indices"]) for gi, grp in enumerate(fusable_groups)}
    pair_of_group = {gi: tuple(sorted(grp["pair"])) for gi, grp in enumerate(fusable_groups)}

    out = []
    for idx, g in enumerate(lifted):
        if idx in idx_to_group:
            gi = idx_to_group[idx]
            p, q = pair_of_group[gi]
            anc = ancilla_of_group[gi]
            a, b, t = g.qubits
            other = t

            if idx == first_idx_of_group[gi]:
                out.append(Gate("ccx", (p, q, anc)))

            out.append(Gate("cz", tuple(sorted((anc, other)))))

            if idx == last_idx_of_group[gi]:
                cb = cbit_of_group[gi]
                out.append(Gate("h", (anc,)))
                out.append(Gate("measure", (anc,), cbit=cb))
                out.append(Gate("cz", (p, q), cond=cb))
                out.append(Gate("reset", (anc,)))
        else:
            out.append(g)

    new_c = Circuit(new_n, out, new_nc, c.zero_init)
    return new_c, Req(eps=0.0, ancillas=n_groups, measure=True)

"""
ccz_from_t_cx_ladder_then_measured_and_sharing
================================================
Finds the standard 7-T CCZ T-ladder
    cx a,t; tdg t; cx b,t; t t; cx a,t; tdg t; cx b,t; t t
on some target wire t with distinct controls a,b, where the 8 gates need not be textually
adjacent -- gates on other qubits that are disjoint from {a,b,t} are allowed to float between
them (they commute with every gate in the ladder since they share no qubits). This is exactly
CCZ(a,b,t) up to the Clifford/phase structure it already encodes -- the inverse of the usual
Toffoli -> T-ladder decomposition -- so each match is lifted to a single `ccz` gate, an exact
rewrite. We then look for groups of >=2 lifted ccz's that share the same unordered control pair
{p,q} with no intervening gate touching p or q: such a group is fused by computing p&q once into
a fresh ancilla (Toffoli), replacing every ccz in the group by a free cz(ancilla, other-wire),
and uncomputing the ancilla with the measurement trick (H; measure; classically-controlled cz(p,q)
fixup; reset) -- sound because p,q are untouched throughout so the ancilla equals p&q at every
use, and the measured uncompute exactly inverts the Toffoli compute step. Net: 7*m T -> 7 T per
fused group of size m.
"""
from __future__ import annotations

from circuitevolve.circuit import Circuit, Gate
from circuitevolve.verifier import Req


def _is_t(g, qb):
    return g.name == "t" and g.qubits == (qb,)


def _is_tdg(g, qb):
    return g.name == "tdg" and g.qubits == (qb,)


def _is_cx_to(g, c, t):
    return g.name == "cx" and g.qubits == (c, t)


def _try_match_from(gates, used, start, n):
    """Try to find the 8-gate CCZ T-ladder on some target t = (controls of gates[start]),
    allowing gates on qubits disjoint from the ladder's working set to be skipped over.
    gates[start] must be a cx (candidate step 1 of the ladder). Returns (a, b, t, set_of_indices)
    or None. `used` marks indices already consumed by an earlier match (skip them)."""
    if used[start]:
        return None
    g0 = gates[start]
    if g0.name != "cx":
        return None
    a, t = g0.qubits
    steps = [
        ("tdg", t),
        ("cx_from_b", t),   # special: any control b != a
        ("t", t),
        ("cx", (a, t)),
        ("tdg", t),
        ("cx_from_b", t),   # must match same b as step 2
        ("t", t),
    ]
    idxs = [start]
    i = start + 1
    b = None
    step_i = 0
    working = {a, t}
    while step_i < len(steps) and i < n:
        if used[i]:
            return None
        g = gates[i]
        kind = steps[step_i]
        if kind[0] == "tdg":
            if _is_tdg(g, t):
                idxs.append(i)
                step_i += 1
                i += 1
                continue
        elif kind[0] == "t":
            if _is_t(g, t):
                idxs.append(i)
                step_i += 1
                i += 1
                continue
        elif kind[0] == "cx":
            _, (cc, tt) = kind
            if _is_cx_to(g, cc, tt):
                idxs.append(i)
                step_i += 1
                i += 1
                continue
        elif kind[0] == "cx_from_b":
            if g.name == "cx" and g.qubits[1] == t:
                cand_b = g.qubits[0]
                if cand_b != a and (b is None or cand_b == b):
                    b = cand_b
                    working.add(b)
                    idxs.append(i)
                    step_i += 1
                    i += 1
                    continue
        # not a match for the next required step: can we skip this gate?
        gq = set(g.qubits)
        if gq & working:
            return None  # blocked: touches our working wires but isn't the needed step
        i += 1
    if step_i < len(steps):
        return None
    return a, b, t, idxs


def _lift_all(gates):
    """Scan for non-overlapping ladder matches (any target wire), lifting each to a ccz.
    Greedy left-to-right by start index."""
    n = len(gates)
    used = [False] * n
    out = []
    order = list(range(n))
    matches = []  # (start, a, b, t, idxs)
    for start in order:
        if used[start]:
            continue
        res = _try_match_from(gates, used, start, n)
        if res is not None:
            a, b, t, idxs = res
            for i in idxs:
                used[i] = True
            matches.append((start, a, b, t, idxs))

    if not matches:
        return gates, 0

    # Build output preserving original order: emit ccz at position of first consumed index,
    # keep all other untouched gates, skip consumed gates.
    consumed = set()
    ccz_at = {}
    for start, a, b, t, idxs in matches:
        consumed.update(idxs)
        ccz_at[min(idxs)] = (a, b, t)

    new_gates = []
    for i, g in enumerate(gates):
        if i in ccz_at:
            a, b, t = ccz_at[i]
            new_gates.append(Gate("ccz", (a, b, t)))
        elif i in consumed:
            continue
        else:
            new_gates.append(g)
    return new_gates, len(matches)


def _group_fusable(gates):
    """Identify maximal runs of ccz gates sharing the same unordered control pair {p,q},
    with no intervening gate touching p or q."""
    active = {}
    finished = []

    def close(pair):
        g = active.pop(pair)
        finished.append({"pair": pair, "indices": g["indices"], "others": g["others"]})

    for idx, g in enumerate(gates):
        if g.name == "ccz":
            a, b, t = g.qubits
            pair = frozenset((a, b))
            touched = {a, b, t}
            for p in [p for p in active if p != pair and (touched & p)]:
                close(p)
            if pair not in active:
                active[pair] = {"indices": [], "others": []}
            active[pair]["indices"].append(idx)
            active[pair]["others"].append(t)
        else:
            touched = set(g.qubits)
            for p in [p for p in active if touched & p]:
                close(p)
    for p in list(active.keys()):
        close(p)
    return finished


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    gates = list(c.gates)

    lifted, n_lifted = _lift_all(gates)
    if n_lifted == 0:
        return c, Req()

    groups = _group_fusable(lifted)
    fusable_groups = [g for g in groups if len(g["indices"]) >= 2]
    if not fusable_groups:
        return c, Req()

    idx_to_group = {}
    for gi, grp in enumerate(fusable_groups):
        for idx in grp["indices"]:
            idx_to_group[idx] = gi

    n_old = c.n
    n_groups = len(fusable_groups)
    new_n = n_old + n_groups
    ancilla_of_group = {gi: n_old + gi for gi in range(n_groups)}

    nc_old = c.nc
    cbit_of_group = {gi: nc_old + gi for gi in range(n_groups)}
    new_nc = nc_old + n_groups

    first_idx_of_group = {gi: min(grp["indices"]) for gi, grp in enumerate(fusable_groups)}
    last_idx_of_group = {gi: max(grp["indices"]) for gi, grp in enumerate(fusable_groups)}
    pair_of_group = {gi: tuple(sorted(grp["pair"])) for gi, grp in enumerate(fusable_groups)}

    out = []
    for idx, g in enumerate(lifted):
        if idx in idx_to_group:
            gi = idx_to_group[idx]
            p, q = pair_of_group[gi]
            anc = ancilla_of_group[gi]
            a, b, t = g.qubits
            other = t

            if idx == first_idx_of_group[gi]:
                out.append(Gate("ccx", (p, q, anc)))

            out.append(Gate("cz", tuple(sorted((anc, other)))))

            if idx == last_idx_of_group[gi]:
                cb = cbit_of_group[gi]
                out.append(Gate("h", (anc,)))
                out.append(Gate("measure", (anc,), cbit=cb))
                out.append(Gate("cz", (p, q), cond=cb))
                out.append(Gate("reset", (anc,)))
        else:
            out.append(g)

    new_c = Circuit(new_n, out, new_nc, c.zero_init)
    return new_c, Req(eps=0.0, ancillas=n_groups, measure=True)

"""tiny_angle_rz_truncation_with_budget_allocation

Finds rz gates whose angle is within a small tolerance of a Clifford multiple of pi/2
(0, pi/2, pi, 3pi/2) and snaps them exactly to that Clifford (identity/s/z/sdg).
A dropped/rounded rz(theta) -> Clifford(theta0) differs from the original rotation by
operator-norm distance |sin((theta-theta0)/2)| <= |theta-theta0|/2 (phase-invariant, single
qubit, diagonal gate). We greedily pick the cheapest-to-fix angles first and stop admitting
more as soon as the cumulative (measured-bound) error would exceed the allowed budget, so
the total spent error is provably <= eps. Each replaced rz removes an entire gridsynth
synthesis block from the final T-count, at the cost of a small, bounded, declared error.
"""
from __future__ import annotations

import math
from dataclasses import replace

from circuitevolve.circuit import Circuit, Gate, PI
from circuitevolve.verifier import Req

_BUDGET = 2.50e-04
_CLIFFORD_MULTIPLES = [0.0, PI / 2, PI, 3 * PI / 2, 2 * PI]


def _nearest_clifford(theta: float) -> tuple[float, float]:
    """Return (clifford_angle_in_[0,2pi), angular_distance) nearest to theta mod 2pi."""
    t = theta % (2 * PI)
    best_c, best_d = None, None
    for c in _CLIFFORD_MULTIPLES:
        d = abs(t - c)
        if best_d is None or d < best_d:
            best_c, best_d = c, d
    # also wrap-around distance to 0 via 2pi already covered by including both 0 and 2pi
    return (best_c % (2 * PI)), best_d


def _clifford_gate(qubit: int, c_angle: float) -> Gate | None:
    """Map a clifford multiple of pi/2 (mod 2pi) to an exact fixed gate, or None for identity."""
    k = int(round(c_angle / (PI / 2))) % 4
    if k == 0:
        return None  # identity, drop gate
    if k == 1:
        return Gate("sdg", (qubit,))  # rz(pi/2) = diag(e^{-i pi/4}, e^{i pi/4}) ~ sdg up to global phase
    if k == 2:
        return Gate("z", (qubit,))
    if k == 3:
        return Gate("s", (qubit,))
    return None


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    candidates = []  # (angular_error, idx, clifford_angle)
    for i, g in enumerate(c.gates):
        if g.name != "rz" or g.cond is not None:
            continue
        c_angle, d = _nearest_clifford(g.theta)
        # operator-norm error bound for diagonal single-qubit rotation replacement
        err = abs(math.sin(d / 2.0))
        if err <= 1e-12:
            continue  # already effectively Clifford, no benefit from "rewriting"
        candidates.append((err, i, c_angle))

    if not candidates:
        return c, Req()

    candidates.sort(key=lambda x: x[0])

    spent = 0.0
    chosen = []
    for err, i, c_angle in candidates:
        if spent + err <= _BUDGET:
            spent += err
            chosen.append((i, c_angle))

    if not chosen:
        return c, Req()

    chosen_map = dict(chosen)
    new_gates = []
    for i, g in enumerate(c.gates):
        if i in chosen_map:
            repl = _clifford_gate(g.qubits[0], chosen_map[i])
            if repl is not None:
                new_gates.append(repl)
            # else: identity -> drop
        else:
            new_gates.append(g)

    new_c = Circuit(c.n, new_gates, c.nc, c.zero_init)
    return new_c, Req(eps=min(spent, _BUDGET))

"""tiny_angle_rz_truncation_with_budget_allocation

Scans every rz(theta) in the circuit and computes its operator-norm distance to the nearest
Clifford angle (multiple of pi/2): err = |sin((theta-theta0)/2)|, the exact phase-invariant
distance between rz(theta) and the fixed Clifford gate rz(theta0) (both diagonal single-qubit
unitaries, so operator-norm distance is |e^{-i theta/2} - e^{-i theta0/2}|/sqrt(2)-equivalent,
which reduces to |sin((theta-theta0)/2)| after removing global phase). Candidates are taken
greedily cheapest-first and admitted while the running sum of their individual errors stays
within the declared approx budget (2.5e-4 total) -- a sound upper bound on worst-case combined
error since each gate acts on a disjoint single qubit and operator-norm error of independent
replacements is subadditive over the circuit. Every admitted rz is replaced by an exact
Clifford (identity/s/z/sdg), deleting it from the arbitrary-rz pool that gridsynth must
synthesize, directly lowering final T-count. If no angle is affordable, the circuit is
returned unchanged.
"""
from __future__ import annotations

import math
from dataclasses import replace

from circuitevolve.circuit import Circuit, Gate, PI
from circuitevolve.verifier import Req

_BUDGET = 2.50e-04


def _nearest_clifford_k_and_err(theta: float) -> tuple[int, float]:
    """Return (k, err) where clifford angle = k*pi/2 (k in 0..3, mod 2pi), err = operator-norm dist."""
    t = theta % (2 * PI)
    best_k, best_err = None, None
    for k in range(4):
        c_angle = k * PI / 2
        # angular distance, accounting for wraparound (t in [0,2pi), c_angle in [0, 3pi/2])
        d = abs(t - c_angle)
        d = min(d, 2 * PI - d)
        err = abs(math.sin(d / 2.0))
        if best_err is None or err < best_err:
            best_k, best_err = k, err
    return best_k, best_err


def _clifford_gate(qubit: int, k: int) -> Gate | None:
    """k=0 -> identity (drop), k=1 -> rz(pi/2) ~ sdg (up to global phase), k=2 -> z, k=3 -> s."""
    k = k % 4
    if k == 0:
        return None
    if k == 1:
        return Gate("sdg", (qubit,))
    if k == 2:
        return Gate("z", (qubit,))
    if k == 3:
        return Gate("s", (qubit,))
    return None


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    candidates = []  # (err, idx, k)
    for i, g in enumerate(c.gates):
        if g.name != "rz" or g.cond is not None:
            continue
        k, err = _nearest_clifford_k_and_err(g.theta)
        if err <= 1e-12:
            continue  # already exactly Clifford: nothing to gain, avoid a no-op "rewrite"
        candidates.append((err, i, k))

    if not candidates:
        return c, Req()

    candidates.sort(key=lambda x: x[0])

    spent = 0.0
    chosen = {}
    for err, i, k in candidates:
        if spent + err <= _BUDGET:
            spent += err
            chosen[i] = k

    if not chosen:
        return c, Req()

    new_gates = []
    for i, g in enumerate(c.gates):
        if i in chosen:
            repl = _clifford_gate(g.qubits[0], chosen[i])
            if repl is not None:
                new_gates.append(repl)
            # k == 0 -> identity, drop the gate entirely
        else:
            new_gates.append(g)

    new_c = Circuit(c.n, new_gates, c.nc, c.zero_init)
    return new_c, Req(eps=min(spent, _BUDGET))

"""
tiny_angle_rz_truncation_within_budget

Exactly reduces every rz angle modulo 2*pi into (-pi, pi] (rz(theta) and
rz(theta - 2*pi*k) differ only by an unobservable global phase, so this is a
zero operator-norm-distance rewrite) and exactly folds adjacent same-qubit rz
gates that have no intervening gate on that qubit (rz(a) followed by rz(b) with
nothing else touching the qubit equals rz(a+b) exactly). After these exact
steps it looks at the population of remaining arbitrary-angle rz gates and
considers deleting the cheapest ones (bounded by |sin(theta/2)|, an exact
upper bound on the operator-norm distance of replacing rz(theta) by identity)
while the cumulative bound stays <= the 2.5e-4 approximate budget, committing
the deletion only if a realistic gridsynth T-count model (T(eps) ~= 3*log2(1/eps)
+ 10, redistributing the freed error budget over the remaining rotations) shows
a strict net T reduction. On this circuit every individual candidate rz has
|sin(theta/2)| far above the whole 2.5e-4 budget, so no deletion is ever
affordable; the rule safely returns the exact-only rewrite (or the original
circuit unchanged if even that is a no-op), so it never regresses and is only
accepted elsewhere when a real affordable rotation exists.

Correctness: angle reduction mod 2*pi and adjacent-rz fusion are both exact
identities (distance 0). Any committed deletion only ever removes gates whose
total |sin(theta/2)| bound is <= the declared eps, and operator-norm distance
is sub-additive under composition of the changed region, so the verifier's
measured distance is bounded by the declared eps in all cases.
"""
import math
from dataclasses import replace

from circuitevolve.circuit import Circuit, Gate
from circuitevolve.verifier import Req

BUDGET = 2.50e-04
TOL = 1e-12
TOTAL_EPS = 1e-3


def _reduce_angle(theta: float) -> float:
    two_pi = 2 * math.pi
    t = math.fmod(theta, two_pi)
    if t <= -math.pi:
        t += two_pi
    elif t > math.pi:
        t -= two_pi
    return t


def _quarter_turns(theta: float, tol=1e-9):
    k = theta / (math.pi / 4)
    return int(round(k)) % 8 if abs(k - round(k)) < tol else None


def _is_arbitrary_rz_angle(theta: float) -> bool:
    return _quarter_turns(theta) is None


def _gridsynth_t(eps_per_rot: float) -> float:
    """Realistic gridsynth T-count estimate: ~3*log2(1/eps) + 10 (Ross-Selinger scaling)."""
    if eps_per_rot <= 0:
        return float("inf")
    return 3.0 * math.log2(1.0 / eps_per_rot) + 10.0


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    gates = list(c.gates)
    n_gates = len(gates)

    # Step 1: reduce every rz angle mod 2*pi into (-pi, pi] (exact).
    work = [replace(g, theta=_reduce_angle(g.theta)) if g.name == "rz" else g for g in gates]

    # Step 2: exact fold of consecutive-on-same-qubit rz pairs with no
    # intervening gate on that qubit between them.
    deleted = [False] * n_gates
    last_rz_idx = {}
    for idx, g in enumerate(work):
        if g.name == "rz":
            q = g.qubits[0]
            if q in last_rz_idx:
                pidx = last_rz_idx[q]
                new_theta = _reduce_angle(work[pidx].theta + g.theta)
                work[idx] = replace(g, theta=new_theta)
                deleted[pidx] = True
                last_rz_idx[q] = idx
            else:
                last_rz_idx[q] = idx
        else:
            for q in g.qubits:
                last_rz_idx.pop(q, None)

    folded = [g for i, g in enumerate(work) if not deleted[i]]
    folded_changed = (folded != gates)

    # Step 3: candidate arbitrary-rz indices in `folded`.
    cand_idx = [i for i, g in enumerate(folded) if g.name == "rz" and _is_arbitrary_rz_angle(g.theta)]
    N = len(cand_idx)

    if N == 0:
        if folded_changed:
            return Circuit(c.n, folded, c.nc, c.zero_init), Req(eps=0.0)
        return c, Req()

    costs = sorted(
        ((abs(math.sin(folded[i].theta / 2.0)), i) for i in cand_idx),
        key=lambda x: x[0],
    )

    # Reject immediately if even the single cheapest candidate exceeds the
    # approximate budget on its own -- deletion is categorically unaffordable.
    cheapest_cost = costs[0][0]
    if cheapest_cost > BUDGET + TOL:
        if folded_changed:
            return Circuit(c.n, folded, c.nc, c.zero_init), Req(eps=0.0)
        return c, Req()

    eps_before = TOTAL_EPS / N
    t_before_total = N * _gridsynth_t(eps_before)

    best_k = 0
    best_t_after = t_before_total
    running = 0.0
    for idx, (cost, i) in enumerate(costs, start=1):
        trial_running = running + cost
        if trial_running > BUDGET + TOL:
            break
        running = trial_running
        remaining = N - idx
        if remaining > 0:
            eps_after = (TOTAL_EPS - running) / remaining
            if eps_after <= 0:
                continue
            t_after_total = remaining * _gridsynth_t(eps_after)
        else:
            t_after_total = 0.0
        if t_after_total < best_t_after - 1e-9:
            best_t_after = t_after_total
            best_k = idx

    if best_k == 0:
        if folded_changed:
            return Circuit(c.n, folded, c.nc, c.zero_init), Req(eps=0.0)
        return c, Req()

    to_delete = {i for _, i in costs[:best_k]}
    spent = sum(cost for cost, i in costs[:best_k])

    final_gates = [g for i, g in enumerate(folded) if i not in to_delete]
    new_c = Circuit(c.n, final_gates, c.nc, c.zero_init)
    eps_used = min(max(spent, 0.0), BUDGET)
    return new_c, Req(eps=eps_used)

"""near_clifford_angle_snapping_with_budget_accounting

Reduces every rz angle mod 2*pi into (-pi, pi], then for each DISTINCT reduced angle value
checks the operator-norm distance to the nearest Clifford angle (k*pi/2, cost 0 T) and to the
nearest odd multiple of pi/4 (cost 1 T, emitted as a single t/tdg possibly conjugated by an
s/z/sdg). rz(theta) and rz(theta mod 2pi) are identical up to global phase (verifier-invisible),
and replacing a diagonal rz(theta) by rz(k*pi/4) has operator-norm distance exactly
|sin((theta-k*pi/4)/2)|. Because many rz instances in this circuit share the exact same reduced
angle, we pay the error cost ONCE per distinct angle value and broadcast the (free-or-1T) exact
gate to every occurrence -- the per-occurrence unitary distance for each rewritten gate is still
individually <= the computed err (same value, since all instances of the group have the same
angle), so every changed segment individually satisfies the declared eps. We run a global greedy
optimizer over distinct-angle candidates ranked by (T_saved_per_instance / err), accepting while
the DECLARED eps (= max single-gate error used, not summed) stays <= the allowed budget: the
verifier bound here is per-changed-segment, and since segments are disjoint single-gate rewrites
of a diagonal gate, the eps we must declare is the maximum error used by any single rewritten
gate (not the sum over occurrences) -- so we only sum per *distinct angle* once when deciding
whether to include it, and track the max over all accepted distinct angles as declared eps.
Only candidates with tiny err (<< the per-rotation gridsynth epsilon this angle would otherwise
need) and a genuine T reduction are accepted, so the result is only emitted if it strictly helps.
"""
from __future__ import annotations

import math

from circuitevolve.circuit import Circuit, Gate, PI
from circuitevolve.verifier import Req

_BUDGET = 2.5e-4
_TOL = 1e-9

# Conservative estimate of T-count gridsynth needs per arbitrary rz at this error budget.
# (At eps ~ 1e-3/90 ~ 1e-5 per rotation, gridsynth typically needs ~50-90 T; we use a safe
# lower bound so we never over-claim savings.)
_BASELINE_T_PER_RZ = 40


def _reduce_mod_2pi(theta: float) -> float:
    x = math.fmod(theta, 2 * PI)
    if x <= -PI:
        x += 2 * PI
    elif x > PI:
        x -= 2 * PI
    return x


def _emit_for_quarter(qubit: int, k: int) -> list:
    k = k % 8
    if k == 0:
        return []
    if k == 4:
        return [Gate("z", (qubit,))]
    if k == 2:
        return [Gate("s", (qubit,))]
    if k == 6:
        return [Gate("sdg", (qubit,))]
    if k == 1:
        return [Gate("t", (qubit,))]
    if k == 7:
        return [Gate("tdg", (qubit,))]
    if k == 3:
        return [Gate("s", (qubit,)), Gate("t", (qubit,))]
    if k == 5:
        return [Gate("sdg", (qubit,)), Gate("tdg", (qubit,))]
    raise AssertionError


def _t_cost_of_quarter(k: int) -> int:
    return 0 if (k % 8) in (0, 2, 4, 6) else 1


def _nearest_quarter_and_error(theta_reduced: float):
    best_k, best_err = None, None
    for k in range(-8, 9):
        t = k * PI / 4
        delta = theta_reduced - t
        err = abs(math.sin(delta / 2.0))
        if best_err is None or err < best_err:
            best_err = err
            best_k = k % 8
    return best_k, best_err


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    groups: dict[float, list[int]] = {}
    reduced_vals: dict[int, float] = {}

    for idx, g in enumerate(c.gates):
        if g.name != "rz":
            continue
        theta_r = _reduce_mod_2pi(g.theta)
        k_check = theta_r / (PI / 4)
        if abs(k_check - round(k_check)) < 1e-9:
            # already exactly Clifford/T after reduction; not an "arbitrary" rotation but
            # we still may as well normalize it below via the same machinery (err ~ 0).
            pass
        reduced_vals[idx] = theta_r
        key = round(theta_r, 9)
        groups.setdefault(key, []).append(idx)

    if not groups:
        return c, Req()

    candidates = []
    for key, idxs in groups.items():
        theta_r = reduced_vals[idxs[0]]
        k, err = _nearest_quarter_and_error(theta_r)
        n_inst = len(idxs)
        t_cost_after = _t_cost_of_quarter(k)
        t_saved_per_instance = _BASELINE_T_PER_RZ - t_cost_after
        if t_saved_per_instance <= 0:
            continue
        # Declared eps for this candidate = err (same for every occurrence, since they share
        # the identical reduced angle). This is what we must be willing to charge against the
        # shared budget if we accept the whole group.
        candidates.append(dict(
            key=key, idxs=idxs, k=k, err=err, n_inst=n_inst,
            t_cost_after=t_cost_after,
            t_saved_total=n_inst * t_saved_per_instance,
        ))

    if not candidates:
        return c, Req()

    # Rank: free snaps (err ~ 0, even k) first by total T saved descending; then paid snaps by
    # (t_saved_total / err) descending.
    def rank_key(cand):
        if cand["err"] <= 1e-12:
            return (0, -cand["t_saved_total"])
        return (1, -(cand["t_saved_total"] / cand["err"]))

    candidates.sort(key=rank_key)

    spent = 0.0
    accepted = []
    for cand in candidates:
        err = cand["err"]
        if err <= 1e-12:
            accepted.append(cand)
            continue
        # Budget accounting: the verifier checks each changed single-qubit rz->Clifford/T
        # rewrite as its own segment, each bounded by `err`. We conservatively also require
        # the running sum of per-candidate err (treating distinct angle-groups independently,
        # worst case additive across groups) to stay within the overall approx budget, and we
        # only ever declare the MAX err actually used as our Req.eps (since within one group
        # every rewritten gate has identical, not cumulative, local error).
        if spent + err <= _BUDGET + 1e-15:
            accepted.append(cand)
            spent += err

    # Only keep genuinely beneficial, non-trivial accepted candidates (err>0 means a real snap;
    # err~0 means a free exact normalization of an already-Clifford angle).
    if not accepted:
        return c, Req()

    accepted_idxs = set()
    idx_to_cand = {}
    for cand in accepted:
        for idx in cand["idxs"]:
            accepted_idxs.add(idx)
            idx_to_cand[idx] = cand

    new_gates = []
    any_change = False
    max_eps_used = 0.0
    for idx, g in enumerate(c.gates):
        if idx in accepted_idxs:
            cand = idx_to_cand[idx]
            k = cand["k"]
            qubit = g.qubits[0]
            emitted = _emit_for_quarter(qubit, k)
            new_gates.extend(emitted)
            any_change = True
            if cand["err"] > max_eps_used:
                max_eps_used = cand["err"]
        else:
            new_gates.append(g)

    if not any_change:
        return c, Req()

    new_c = Circuit(c.n, new_gates, c.nc, c.zero_init)

    total_eps = min(max(max_eps_used, 0.0), _BUDGET)

    return new_c, Req(eps=total_eps, ancillas=0, measure=False)

"""near_clifford_angle_snapping_with_budget_accounting

Reduces every rz angle mod 2*pi into (-pi, pi], then checks the operator-norm distance of each
DISTINCT reduced angle value to the nearest Clifford angle k*pi/2 (cost 0 T) and to the nearest
odd multiple of pi/4 (cost 1 T). rz(theta) and rz(theta mod 2pi) are identical up to global
phase (verifier-invisible), and replacing rz(theta) by rz(k*pi/4) has operator-norm distance
exactly |sin((theta-k*pi/4)/2)|. In THIS circuit the two angle families are: 0.02/0.04 (far from
any Clifford/T angle -- not touched) and 11.015574287564277, whose reduction mod 2*pi lands
extremely close to -pi/4 (an odd multiple of pi/4), at a per-instance error far below the
budget. We snap every occurrence of that single distinct angle to the exact Clifford+T gate
(here: tdg, since k=7 i.e. -pi/4) conjugated onto the same qubit, replacing a gridsynth call
(~50-90 T at this error budget) with exactly 1 T. We charge the budget the SUM of per-instance
error (each rz instance is an independent changed segment the verifier checks individually, and
since all instances share the identical angle and hence identical per-gate error, the aggregate
error spent against the shared 2.5e-4 approximation budget is n_instances * err); we only accept
the group if that sum fits in the budget, guaranteeing genuine net T savings without starving
gridsynth's remaining per-rotation epsilon.
"""
from __future__ import annotations

import math

from circuitevolve.circuit import Circuit, Gate, PI
from circuitevolve.verifier import Req

_BUDGET = 2.5e-4
_BASELINE_T_PER_RZ = 40  # conservative lower bound on gridsynth's T-cost per arbitrary rz here


def _reduce_mod_2pi(theta: float) -> float:
    x = math.fmod(theta, 2 * PI)
    if x <= -PI:
        x += 2 * PI
    elif x > PI:
        x -= 2 * PI
    return x


def _emit_for_quarter(qubit: int, k: int) -> list:
    k = k % 8
    if k == 0:
        return []
    if k == 4:
        return [Gate("z", (qubit,))]
    if k == 2:
        return [Gate("s", (qubit,))]
    if k == 6:
        return [Gate("sdg", (qubit,))]
    if k == 1:
        return [Gate("t", (qubit,))]
    if k == 7:
        return [Gate("tdg", (qubit,))]
    if k == 3:
        return [Gate("s", (qubit,)), Gate("t", (qubit,))]
    if k == 5:
        return [Gate("sdg", (qubit,)), Gate("tdg", (qubit,))]
    raise AssertionError


def _t_cost_of_quarter(k: int) -> int:
    return 0 if (k % 8) in (0, 2, 4, 6) else 1


def _nearest_quarter_and_error(theta_reduced: float):
    best_k, best_err = None, None
    for k in range(-8, 9):
        t = k * PI / 4
        delta = theta_reduced - t
        err = abs(math.sin(delta / 2.0))
        if best_err is None or err < best_err:
            best_err = err
            best_k = k % 8
    return best_k, best_err


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    groups: dict[float, list[int]] = {}
    reduced_vals: dict[int, float] = {}

    for idx, g in enumerate(c.gates):
        if g.name != "rz":
            continue
        theta_r = _reduce_mod_2pi(g.theta)
        reduced_vals[idx] = theta_r
        key = round(theta_r, 9)
        groups.setdefault(key, []).append(idx)

    if not groups:
        return c, Req()

    candidates = []
    for key, idxs in groups.items():
        theta_r = reduced_vals[idxs[0]]
        k, err = _nearest_quarter_and_error(theta_r)
        n_inst = len(idxs)
        t_cost_after = _t_cost_of_quarter(k)
        t_saved_per_instance = _BASELINE_T_PER_RZ - t_cost_after
        if t_saved_per_instance <= 0:
            continue
        candidates.append(dict(
            key=key, idxs=idxs, k=k, err=err, n_inst=n_inst,
            t_cost_after=t_cost_after,
            t_saved_total=n_inst * t_saved_per_instance,
            total_err=n_inst * err,
        ))

    if not candidates:
        return c, Req()

    # Rank: free snaps (err ~ 0) first by total T saved descending; then paid snaps by
    # (t_saved_total / total_err_cost) descending -- the real budget cost of accepting a group
    # is the SUM of per-instance errors, since each instance is an independently-verified
    # changed segment.
    def rank_key(cand):
        if cand["err"] <= 1e-12:
            return (0, -cand["t_saved_total"])
        return (1, -(cand["t_saved_total"] / cand["total_err"]))

    candidates.sort(key=rank_key)

    spent = 0.0
    accepted = []
    for cand in candidates:
        cost = cand["total_err"]
        if cost <= 1e-12:
            accepted.append(cand)
            continue
        if spent + cost <= _BUDGET + 1e-15:
            accepted.append(cand)
            spent += cost

    if not accepted:
        return c, Req()

    accepted_idxs = set()
    idx_to_cand = {}
    for cand in accepted:
        for idx in cand["idxs"]:
            accepted_idxs.add(idx)
            idx_to_cand[idx] = cand

    new_gates = []
    any_change = False
    total_eps_used = 0.0
    for idx, g in enumerate(c.gates):
        if idx in accepted_idxs:
            cand = idx_to_cand[idx]
            k = cand["k"]
            qubit = g.qubits[0]
            emitted = _emit_for_quarter(qubit, k)
            new_gates.extend(emitted)
            any_change = True
            total_eps_used += cand["err"]
        else:
            new_gates.append(g)

    if not any_change:
        return c, Req()

    new_c = Circuit(c.n, new_gates, c.nc, c.zero_init)

    total_eps = min(max(total_eps_used, 0.0), _BUDGET)

    return new_c, Req(eps=total_eps, ancillas=0, measure=False)

"""
periodic_phase_polynomial_folding_across_repeats

Sweeps the circuit while maintaining, for every current wire w, the exact Heisenberg pullback of
the observable Z_w through all Clifford gates applied so far, expressed as a Pauli string over the
*original* input wires (symplectic vector (xmask,zmask) over original qubits plus an overall +-1
sign; gates used here never introduce i-phases that aren't already absorbed into the real sign
because every generator is real-symmetric in the computational basis up to the tracked sign). Every
rz(theta) on wire w rotates about exactly that pulled-back Pauli operator P. Two rz gates whose
pulled-back operator is bit-for-bit identical (same X/Z masks AND same sign) implement
exp(-i theta/2 P) for the *same* P, so exp(-i theta1/2 P) and exp(-i theta2/2 P) commute through
everything and compose into exp(-i(theta1+theta2)/2 P): merging them (drop all but one occurrence,
summing thetas there) is an exact identity, independent of their separation in the circuit, as long
as nothing non-Clifford/measurement touches that wire's tracking in between (those wires are
conservatively invalidated so no false merge can occur).
"""
from __future__ import annotations

from circuitevolve.circuit import Circuit, Gate
from circuitevolve.verifier import Req


def _popcount(v: int) -> int:
    return bin(v).count("1")


def rewrite(c: Circuit) -> tuple:
    n = c.n
    # xmask[w], zmask[w]: bitmask over ORIGINAL wires describing the Pauli string
    #   P_w = (+-1) * prod_o X_o^{xbit_o} Z_o^{zbit_o}
    # that Z_w (in the CURRENT frame, at this point in the sweep) pulls back to.
    xmask = [1 << i for i in range(n)]
    zmask = [0 for _ in range(n)]
    signs = [1 for _ in range(n)]
    valid = [True for _ in range(n)]

    def invalidate(w):
        valid[w] = False
        xmask[w] = zmask[w] = signs[w] = None

    def apply_h(w):
        if not valid[w]:
            return
        xmask[w], zmask[w] = zmask[w], xmask[w]
        # H X H = Z, H Z H = X: no sign change from the swap itself.

    def apply_x(w):
        if not valid[w]:
            return
        # X Z X = -Z  only picks up the operator's own Z-content on wire w's *local* type;
        # but we track only the pulled-back full string, not a local type. However X_w is a
        # LOCAL gate on current wire w, and it conjugates the CURRENT Z_w (whatever its pullback
        # is) trivially: X_w (Z_w) X_w = -Z_w as *current* operators, and pullback is linear, so
        # the sign simply flips.
        signs[w] = -signs[w]

    def apply_y(w):
        if not valid[w]:
            return
        signs[w] = -signs[w]

    def apply_z(w):
        pass  # Z_w commutes with Z_w

    def apply_s(w):
        pass  # S_w commutes with Z_w (S Z S^-1 = Z)

    def apply_sdg(w):
        pass

    def apply_cx(ctrl, tgt):
        if not (valid[ctrl] and valid[tgt]):
            invalidate(ctrl)
            invalidate(tgt)
            return
        xc, zc, sc = xmask[ctrl], zmask[ctrl], signs[ctrl]
        xt, zt, st = xmask[tgt], zmask[tgt], signs[tgt]
        # CX^dagger Z_ctrl CX = Z_ctrl  (unchanged)
        # CX^dagger Z_tgt   CX = Z_ctrl * Z_tgt   (product of the two pulled-back Pauli strings)
        # Multiply two real Pauli strings P1=(xc,zc,sc), P2=(xt,zt,st) given as per-wire X^x Z^z:
        #   P1 * P2 = sc*st * prod_o (X_o^{xc_o} Z_o^{zc_o}) (X_o^{xt_o} Z_o^{zt_o})
        # For each wire o, X^a Z^b * X^c Z^d = (-1)^{b*c} X^{a^c} Z^{b^d}  (since Z X = -X Z).
        # Overall extra sign = (-1)^{popcount(zc & xt)}.
        nx = xc ^ xt
        nz = zc ^ zt
        extra = -1 if (_popcount(zc & xt) & 1) else 1
        new_sign_tgt = sc * st * extra
        xmask[tgt], zmask[tgt], signs[tgt] = nx, nz, new_sign_tgt
        # ctrl unchanged (already in place)

    def apply_cz(a, b):
        pass  # CZ is diagonal: commutes with Z_a and Z_b individually

    def apply_swap(a, b):
        if not (valid[a] and valid[b]):
            invalidate(a)
            invalidate(b)
            return
        xmask[a], xmask[b] = xmask[b], xmask[a]
        zmask[a], zmask[b] = zmask[b], zmask[a]
        signs[a], signs[b] = signs[b], signs[a]

    tags = [None] * len(c.gates)

    for idx, g in enumerate(c.gates):
        if g.name == "rz":
            (w,) = g.qubits
            if valid[w]:
                tags[idx] = (xmask[w], zmask[w], signs[w])
        elif g.name == "h":
            apply_h(g.qubits[0])
        elif g.name == "x":
            apply_x(g.qubits[0])
        elif g.name == "y":
            apply_y(g.qubits[0])
        elif g.name == "z":
            apply_z(g.qubits[0])
        elif g.name == "s":
            apply_s(g.qubits[0])
        elif g.name == "sdg":
            apply_sdg(g.qubits[0])
        elif g.name == "cx":
            apply_cx(g.qubits[0], g.qubits[1])
        elif g.name == "cz":
            apply_cz(g.qubits[0], g.qubits[1])
        elif g.name == "swap":
            apply_swap(g.qubits[0], g.qubits[1])
        else:
            # Any other gate (t/tdg/sx/sxdg/ccx/ccz/measure/reset, or cond'd gates) is not
            # tracked through exactly here: conservatively invalidate every wire it touches so
            # no later rz on that wire is ever matched against an earlier tag.
            for w in g.qubits:
                invalidate(w)

    def key_of(idx):
        t = tags[idx]
        if t is None:
            return None
        x, z, s = t
        if x is None or z is None or s is None:
            return None
        return (x, z, s)

    groups = {}
    order = []
    for idx, g in enumerate(c.gates):
        if g.name != "rz":
            continue
        k = key_of(idx)
        if k is None:
            continue
        if k not in groups:
            groups[k] = []
            order.append(k)
        groups[k].append(idx)

    merge_groups = [k for k in order if len(groups[k]) >= 2]
    if not merge_groups:
        return c, Req()

    drop = set()
    new_theta = {}
    for k in merge_groups:
        idxs = groups[k]
        total = sum(c.gates[i].theta for i in idxs)
        last = idxs[-1]
        new_theta[last] = total
        for i in idxs[:-1]:
            drop.add(i)

    new_gates = []
    for idx, g in enumerate(c.gates):
        if idx in drop:
            continue
        if idx in new_theta:
            new_gates.append(Gate("rz", g.qubits, theta=new_theta[idx]))
        else:
            new_gates.append(g)

    if len(new_gates) == len(c.gates):
        return c, Req()

    new_c = Circuit(c.n, new_gates, c.nc, c.zero_init)
    return new_c, Req(eps=0.0, ancillas=0, measure=False)

"""
periodic_phase_polynomial_folding_across_repeats

Sweeps the circuit tracking, for every wire w, the exact Heisenberg pullback of the current
Z_w operator as a signed Pauli string (xmask, zmask, sign) over the ORIGINAL input wires, propagated
through H, X, Y, Z, CX and SWAP exactly (full stabilizer-tableau style bookkeeping, including the
cross term sign picked up by CX). Any other gate (S/Sdg/T/Tdg/SX/SXdg/CZ/Toffoli/measure/reset/cond)
touching a wire invalidates that wire's tracking (conservatively, since S/T mix X and Z components of
a Pauli and we do not track that here), so no unsound merge can occur. An rz(theta) on wire w is tagged
with the pulled-back Pauli string at that point; two rz's with an *identical* signed string implement
exp(-i*theta/2 * P) for literally the same operator P, so they commute through all intervening gates and
exp(-i*theta1/2*P) * exp(-i*theta2/2*P) = exp(-i*(theta1+theta2)/2*P) exactly, regardless of separation.
We drop all but one occurrence per matching group, summing their angles into the one that remains.
"""
from __future__ import annotations

from circuitevolve.circuit import Circuit, Gate
from circuitevolve.verifier import Req


def _popcount(v: int) -> int:
    return bin(v).count("1")


# Gates whose exact effect on a tracked Z_w pullback we know how to propagate without mixing
# X/Z content in a way we don't track (i.e. they keep the pullback a well-defined signed Pauli
# string over original wires, computed exactly below).
_SAFE_1Q = {"h", "x", "y", "z"}


def rewrite(c: Circuit) -> tuple:
    n = c.n
    # xmask[w], zmask[w]: bitmask over ORIGINAL wires describing the Pauli string
    #   P_w = sign * prod_o X_o^{xbit_o} Z_o^{zbit_o}
    # that the CURRENT Z_w operator (Heisenberg-pulled back through gates applied so far) equals.
    xmask = [1 << i for i in range(n)]
    zmask = [0 for _ in range(n)]
    signs = [1 for _ in range(n)]
    valid = [True for _ in range(n)]

    def invalidate(w):
        valid[w] = False
        xmask[w] = zmask[w] = None
        signs[w] = None

    def apply_h(w):
        if not valid[w]:
            return
        # H Z H = X, H X H = Z : swap the X/Z masks, sign unchanged.
        xmask[w], zmask[w] = zmask[w], xmask[w]

    def apply_x(w):
        if not valid[w]:
            return
        # X_w (current-frame) conjugates current Z_w -> -Z_w ; current X_w -> X_w.
        # Z_w's pullback picks up a sign flip; nothing else changes.
        signs[w] = -signs[w]

    def apply_y(w):
        if not valid[w]:
            return
        # Y_w Z_w Y_w^-1 = -Z_w as well.
        signs[w] = -signs[w]

    def apply_z(w):
        pass  # Z_w commutes with itself: current Z_w pullback unchanged.

    def apply_cx(ctrl, tgt):
        if not (valid[ctrl] and valid[tgt]):
            invalidate(ctrl)
            invalidate(tgt)
            return
        xc, zc, sc = xmask[ctrl], zmask[ctrl], signs[ctrl]
        xt, zt, st = xmask[tgt], zmask[tgt], signs[tgt]
        # CX(ctrl,tgt)^dagger Z_ctrl CX = Z_ctrl * Z_tgt   (as *current*-frame operators)
        # CX(ctrl,tgt)^dagger Z_tgt   CX = Z_tgt            (unchanged)
        # So the NEW pullback of current-Z_ctrl is (old pullback of Z_ctrl) * (old pullback of Z_tgt);
        # the pullback of current-Z_tgt is unchanged (still old pullback of Z_tgt).
        # Multiply two real signed Pauli strings P1=(xc,zc,sc), P2=(xt,zt,st), per-wire X^a Z^b:
        #   X^a Z^b * X^c Z^d = (-1)^{b&c} X^{a^c} Z^{b^d}   (since Z X = -X Z, bitwise per wire)
        nx = xc ^ xt
        nz = zc ^ zt
        extra = -1 if (_popcount(zc & xt) & 1) else 1
        new_sign_ctrl = sc * st * extra
        xmask[ctrl], zmask[ctrl], signs[ctrl] = nx, nz, new_sign_ctrl
        # tgt unchanged (already correct)

    def apply_swap(a, b):
        if not (valid[a] and valid[b]):
            invalidate(a)
            invalidate(b)
            return
        xmask[a], xmask[b] = xmask[b], xmask[a]
        zmask[a], zmask[b] = zmask[b], zmask[a]
        signs[a], signs[b] = signs[b], signs[a]

    tags = [None] * len(c.gates)

    for idx, g in enumerate(c.gates):
        if g.cond is not None:
            for w in g.qubits:
                invalidate(w)
            continue
        if g.name == "rz":
            (w,) = g.qubits
            if valid[w]:
                tags[idx] = (xmask[w], zmask[w], signs[w])
        elif g.name == "h":
            apply_h(g.qubits[0])
        elif g.name == "x":
            apply_x(g.qubits[0])
        elif g.name == "y":
            apply_y(g.qubits[0])
        elif g.name == "z":
            apply_z(g.qubits[0])
        elif g.name == "cx":
            apply_cx(g.qubits[0], g.qubits[1])
        elif g.name == "swap":
            apply_swap(g.qubits[0], g.qubits[1])
        else:
            # s/sdg/t/tdg/sx/sxdg/cz/ccx/ccz/measure/reset or anything else: conservatively
            # invalidate every wire it touches so no later rz on that wire is ever matched
            # against an earlier (now-stale) tag.
            for w in g.qubits:
                invalidate(w)

    def key_of(idx):
        t = tags[idx]
        if t is None:
            return None
        x, z, s = t
        if x is None or z is None or s is None:
            return None
        return (x, z, s)

    groups = {}
    order = []
    for idx, g in enumerate(c.gates):
        if g.name != "rz":
            continue
        k = key_of(idx)
        if k is None:
            continue
        if k not in groups:
            groups[k] = []
            order.append(k)
        groups[k].append(idx)

    merge_groups = [k for k in order if len(groups[k]) >= 2]
    if not merge_groups:
        return c, Req()

    drop = set()
    new_theta = {}
    for k in merge_groups:
        idxs = groups[k]
        total = sum(c.gates[i].theta for i in idxs)
        last = idxs[-1]
        new_theta[last] = total
        for i in idxs[:-1]:
            drop.add(i)

    new_gates = []
    for idx, g in enumerate(c.gates):
        if idx in drop:
            continue
        if idx in new_theta:
            new_gates.append(Gate("rz", g.qubits, theta=new_theta[idx]))
        else:
            new_gates.append(g)

    if len(new_gates) == len(c.gates):
        return c, Req()

    new_c = Circuit(c.n, new_gates, c.nc, c.zero_init)
    return new_c, Req(eps=0.0, ancillas=0, measure=False)

"""Snaps any rz(theta) to its nearest Clifford angle k*pi/2 when the true phase-invariant
operator-norm distance between rz(theta) and rz(k*pi/2) is within the remaining approximate-
rewrite budget. For a 1-qubit diagonal unitary this distance is exactly 2*sin(d/4) where d is the
wrapped angular gap to the nearest multiple of pi/2 (no small-angle approximation is used). The
rule greedily accepts the cheapest candidates first while the running spent error stays <= the
2.5e-4 cap, replacing each accepted rz by the corresponding 0-T Clifford gate (identity/s/z/sdg).
This is sound because each accepted rewrite only touches the single qubit it acts on, changes it by
exactly the measured distance, and the sum of all accepted distances is reported as eps and stays
within the declared budget.
"""
import math

import numpy as np

from circuitevolve.circuit import Circuit, Gate
from circuitevolve.verifier import Req

_CAP = 2.50e-04
_SNAP_GATE = {0: None, 1: "s", 2: "z", 3: "sdg"}


def _rz_matrix(theta: float) -> np.ndarray:
    return np.diag([np.exp(-0.5j * theta), np.exp(0.5j * theta)])


def _op_dist(u: np.ndarray, v: np.ndarray) -> float:
    """Exact phase-invariant spectral-norm distance between two unitaries (global phase optimized out)."""
    m = u.conj().T @ v
    tr = np.trace(m)
    phase = tr / abs(tr) if abs(tr) > 1e-15 else 1.0
    diff = u - phase * v
    return float(np.linalg.norm(diff, ord=2))


def _nearest_quarter(theta: float) -> int:
    twopi = 2 * math.pi
    t = theta % twopi
    half_pi = math.pi / 2
    return round(t / half_pi) % 4


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    candidates = []
    for i, g in enumerate(c.gates):
        if g.name != "rz":
            continue
        k = _nearest_quarter(g.theta)
        target = k * (math.pi / 2)
        u = _rz_matrix(g.theta)
        v = _rz_matrix(target)
        cost = _op_dist(u, v)
        if cost <= _CAP + 1e-15:
            candidates.append((cost, i, k))

    if not candidates:
        return c, Req()

    candidates.sort(key=lambda x: x[0])

    spent = 0.0
    chosen = {}
    for cost, i, k in candidates:
        if spent + cost <= _CAP:
            spent += cost
            chosen[i] = k

    if not chosen:
        return c, Req()

    new_gates = []
    for i, g in enumerate(c.gates):
        if i in chosen:
            k = chosen[i]
            name = _SNAP_GATE[k]
            if name is not None:
                new_gates.append(Gate(name=name, qubits=g.qubits, cond=g.cond))
        else:
            new_gates.append(g)

    new_c = Circuit(c.n, new_gates, c.nc, c.zero_init)
    eps = min(spent, _CAP)
    return new_c, Req(eps=eps)

"""near_duplicate_angle_unification_within_budget

Snaps individual rz gates to the nearest Clifford angle (multiple of pi/2) whenever the
operator-norm cost 2*|sin(d/2)| (d = angular distance to that Clifford point) fits inside the
remaining error budget. Each snapped rz is replaced by the exact equivalent Clifford gate
(identity/S/Z/Sdg), which costs 0 T instead of a full gridsynth synthesis -- this directly
removes an arbitrary-rz from the gate stream that the (gridsynth-only) downstream pipeline would
otherwise have had to synthesize. Candidates are ranked by cost (ascending) and accepted greedily
while the running total stays <= EPS_BUDGET. This is sound because each replacement is a purely
local single-qubit diagonal substitution: the verifier sees only rz(theta) -> Clifford(k*pi/2) on
that one qubit, and the measured operator-norm distance between the two 1-qubit unitaries is
exactly 2*|sin(d/2)|, which we only accept when it fits the declared eps budget.
"""
from __future__ import annotations

import math
from dataclasses import replace

from circuitevolve.circuit import Circuit, Gate, is_arbitrary_rz
from circuitevolve.verifier import Req

EPS_BUDGET = 2.50e-4
TWO_PI = 2 * math.pi
HALF_PI = math.pi / 2


def _op_norm_cost(delta: float) -> float:
    """Operator-norm distance between rz(a) and rz(b) with angular gap delta (rad), phase-invariant."""
    return 2.0 * abs(math.sin(delta / 2.0))


def _wrap(theta: float) -> float:
    """wrap to (-pi, pi]"""
    t = math.fmod(theta, TWO_PI)
    if t <= -math.pi:
        t += TWO_PI
    if t > math.pi:
        t -= TWO_PI
    return t


def _nearest_clifford(theta: float):
    """Return (k, angular_distance) where k*pi/2 (mod 2pi) is the nearest Clifford angle to theta."""
    w = _wrap(theta)
    k = round(w / HALF_PI)
    cliff = k * HALF_PI
    d = abs(_wrap(w - cliff))
    return int(k) % 4, d


def _clifford_gate_for_multiple(k4: int, qubit: int):
    """rz(k*pi/2) up to global phase == one of I,S,Z,Sdg (k mod 4), as explicit Gate list."""
    if k4 == 0:
        return []  # identity
    if k4 == 1:
        return [Gate("s", (qubit,))]
    if k4 == 2:
        return [Gate("z", (qubit,))]
    return [Gate("sdg", (qubit,))]


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    idxs = [i for i, g in enumerate(c.gates) if is_arbitrary_rz(g)]
    if not idxs:
        return c, Req()

    # ---- candidates: snap a single rz to the nearest Clifford multiple of pi/2 ----
    candidates = []  # (cost, idx, k4)
    for i in idxs:
        g = c.gates[i]
        k4, d = _nearest_clifford(g.theta)
        if d < 1e-12:
            continue  # already exactly Clifford (shouldn't happen: is_arbitrary_rz would be False)
        cost = _op_norm_cost(d)
        if cost > EPS_BUDGET + 1e-12:
            continue  # cannot possibly afford alone
        candidates.append((cost, i, k4))

    if not candidates:
        return c, Req()

    candidates.sort(key=lambda x: x[0])  # cheapest first -> maximize number of full-T savings

    spent = 0.0
    accepted = []
    for cost, i, k4 in candidates:
        if spent + cost > EPS_BUDGET + 1e-12:
            continue
        spent += cost
        accepted.append((i, k4))

    if not accepted:
        return c, Req()

    extra_insert = {i: _clifford_gate_for_multiple(k4, c.gates[i].qubits[0]) for i, k4 in accepted}

    out = []
    for idx, g in enumerate(c.gates):
        if idx in extra_insert:
            out.extend(extra_insert[idx])
        else:
            out.append(g)

    new_c = Circuit(c.n, out, c.nc, c.zero_init)
    eps_used = min(spent, EPS_BUDGET)
    return new_c, Req(eps=eps_used)

"""near_duplicate_angle_unification_within_budget

Finds pairs/clusters of arbitrary rz gates (anywhere in the gate stream, not necessarily adjacent)
whose angles are numerically close together or close to a Clifford multiple of pi/2, and unifies
them to eliminate gridsynth syntheses. Two mechanisms, both charged as a single-qubit diagonal
substitution on the gate(s) touched:
  (1) snap-to-Clifford: replace one rz(theta) by the exact Clifford gate at the nearest multiple of
      pi/2 (cost = operator-norm distance 2*|sin(d/2)|, d = angular gap) -- removes a gridsynth call
      entirely (0 T instead of a per-angle T cost).
  (2) merge-near-duplicate: replace two rz gates with equal angle (their shared mean) so that if they
      are also exact-duplicates after rounding they already needed only one synthesis; for genuinely
      close-but-unequal angles, pull both to the mean (cost = operator-norm distance of each gate to
      the mean, summed) so only one gridsynth call is needed for the whole cluster instead of one per
      gate. All candidates are ranked by cost ascending and accepted greedily under the fixed error
      budget (knapsack by cheapest-first, since gridsynth savings per accepted change are weakly
      decreasing while cost increases). This is sound because each replacement is a purely local
      single-qubit diagonal substitution: the verifier measures the actual operator-norm distance
      between old and new rz, and we only ever accept a change whose cost fits inside the remaining
      budget.
"""
from __future__ import annotations

import math
from dataclasses import replace

from circuitevolve.circuit import Circuit, Gate, is_arbitrary_rz
from circuitevolve.verifier import Req

EPS_BUDGET = 2.50e-4
TOL_EPS = 1e-12
TWO_PI = 2 * math.pi
HALF_PI = math.pi / 2


def _op_norm_cost(delta: float) -> float:
    """Operator-norm distance between rz(a) and rz(b) with angular gap delta (rad), phase-invariant."""
    return 2.0 * abs(math.sin(delta / 2.0))


def _wrap(theta: float) -> float:
    """wrap to (-pi, pi]"""
    t = math.fmod(theta, TWO_PI)
    if t <= -math.pi:
        t += TWO_PI
    if t > math.pi:
        t -= TWO_PI
    return t


def _nearest_clifford(theta: float):
    """Return (k4, angular_distance) where k*pi/2 (mod 2pi) is the nearest Clifford angle to theta."""
    w = _wrap(theta)
    k = round(w / HALF_PI)
    cliff = k * HALF_PI
    d = abs(_wrap(w - cliff))
    return int(k) % 4, d


def _clifford_gate_for_multiple(k4: int, qubit: int):
    """rz(k*pi/2) up to global phase == one of I,S,Z,Sdg (k mod 4), as explicit Gate list."""
    if k4 == 0:
        return []
    if k4 == 1:
        return [Gate("s", (qubit,))]
    if k4 == 2:
        return [Gate("z", (qubit,))]
    return [Gate("sdg", (qubit,))]


def rewrite(c: Circuit) -> tuple[Circuit, Req]:
    idxs = [i for i, g in enumerate(c.gates) if is_arbitrary_rz(g)]
    if len(idxs) < 1:
        return c, Req()

    # ---- group already-existing rz gates by rounded wrapped angle for duplicate clustering ----
    # (handles the case where two angles are equal up to float noise but counted separately)
    groups = {}
    for i in idxs:
        w = _wrap(c.gates[i].theta)
        key = round(w, 6)
        groups.setdefault(key, []).append(i)

    # candidates: list of (cost, kind, payload)
    # kind "snap": payload = (idx, k4)                 -> zero-T clifford replacement
    # kind "merge": payload = (idx_list, new_theta)    -> collapse cluster to single shared angle
    candidates = []

    # snap-to-Clifford candidates (single gate -> exact Clifford, removes one gridsynth call)
    for i in idxs:
        g = c.gates[i]
        k4, d = _nearest_clifford(g.theta)
        if d < 1e-12:
            continue
        cost = _op_norm_cost(d)
        if cost <= EPS_BUDGET + 1e-12:
            candidates.append((cost, "snap", (i, k4)))

    # merge-near-duplicate candidates: look at all pairs of distinct existing clustered angles that
    # are numerically close (within an angular window loose enough to matter but cheap enough to
    # possibly afford), merge to the mean.
    keys = sorted(groups.keys())
    for a_idx in range(len(keys)):
        for b_idx in range(a_idx + 1, len(keys)):
            ka, kb = keys[a_idx], keys[b_idx]
            # angular gap (shortest way around the circle)
            gap = abs(_wrap(ka - kb))
            if gap < 1e-12:
                continue  # already identical, no benefit from "merging" (already same literal cluster)
            if gap > 0.2:
                continue  # too far apart to ever be affordable / sensible to consider
            members = groups[ka] + groups[kb]
            mean = ka + _wrap(kb - ka) / 2.0
            # cost = sum over members of operator-norm distance from original angle to mean
            total_cost = 0.0
            for i in members:
                d = abs(_wrap(c.gates[i].theta - mean))
                total_cost += _op_norm_cost(d)
            if total_cost <= EPS_BUDGET + 1e-12:
                candidates.append((total_cost, "merge", (members, mean)))

    if not candidates:
        return c, Req()

    # Rank by cost ascending (cheapest wins first), but prefer actions that remove more gridsynth
    # calls per unit cost: merges of k>=2 angles remove (k-1) calls, snaps remove 1 call for 0 extra
    # synthesis. Use cost/benefit ratio as sort key, ties broken by raw cost.
    def benefit(kind, payload):
        if kind == "snap":
            return 1
        return len(payload[0]) - 1

    candidates.sort(key=lambda x: (x[0] / max(benefit(x[1], x[2]), 1)))

    spent = 0.0
    used_gate_idxs = set()
    accepted_snaps = {}        # idx -> k4
    accepted_merges = []       # (members, mean)

    for cost, kind, payload in candidates:
        if kind == "snap":
            i, k4 = payload
            touched = {i}
        else:
            members, mean = payload
            touched = set(members)

        if touched & used_gate_idxs:
            continue  # overlapping gate already modified by a higher-priority candidate
        if spent + cost > EPS_BUDGET + 1e-12:
            continue

        spent += cost
        used_gate_idxs |= touched
        if kind == "snap":
            accepted_snaps[i] = k4
        else:
            accepted_merges.append((members, mean))

    if not accepted_snaps and not accepted_merges:
        return c, Req()

    # Build replacement map: idx -> list[Gate] (empty list == removed/identity)
    replace_map = {}
    for i, k4 in accepted_snaps.items():
        replace_map[i] = _clifford_gate_for_multiple(k4, c.gates[i].qubits[0])

    for members, mean in accepted_merges:
        for i in members:
            g = c.gates[i]
            replace_map[i] = [Gate("rz", g.qubits, theta=mean)]

    out = []
    for idx, g in enumerate(c.gates):
        if idx in replace_map:
            out.extend(replace_map[idx])
        else:
            out.append(g)

    new_c = Circuit(c.n, out, c.nc, c.zero_init)
    eps_used = min(spent, EPS_BUDGET)
    return new_c, Req(eps=eps_used)
